/* ============================================================
   داشبورد هنرجو: Student Dashboard
   از آرت‌بورد «داشببود + صفحه کاربر» بازطراحی‌شده با DS رکاد.
   متصل به استور یکپارچه و تعاملی
   ============================================================ */
import { useState, useEffect } from "react";
import { Flame, CheckCircle2, ArrowLeft } from "lucide-react";
import PanelLayout from "./PanelLayout.jsx";
import { getPanelStore, recordDailyStreak } from "../../data/panelStore.js";

const FA = "۰۱۲۳۴۵۶۷۸۹";
const toFa = (n) => String(n).replace(/\d/g, (d) => FA[d]);

/* Play glyph over thumbnails */
const PlayGlyph = () => (
  <span className="play" aria-hidden="true">
    <svg viewBox="0 0 24 24" fill="currentColor"><path d="M8 5v14l11-7z" /></svg>
  </span>
);

export default function Dashboard({ onNavigate }) {
  const [store, setStore] = useState(getPanelStore);
  const [streakSavedToast, setStreakSavedToast] = useState(false);

  useEffect(() => {
    const handleStoreChange = (e) => {
      setStore(e.detail || getPanelStore());
    };
    window.addEventListener("rokad_panel_store_changed", handleStoreChange);
    return () => window.removeEventListener("rokad_panel_store_changed", handleStoreChange);
  }, []);

  const { user, streak, myCourses, events, assignments, certificates } = store;

  const handleRecordStreak = () => {
    recordDailyStreak();
    setStreakSavedToast(true);
    setTimeout(() => setStreakSavedToast(false), 3000);
  };

  const activeCourses = myCourses.filter((c) => c.status !== "done");
  const registeredEvents = events.filter((e) => e.registered);
  const totalCompletedLessons = myCourses.reduce(
    (acc, c) => acc + (c.lessons ? c.lessons.filter((l) => l.done).length : 0),
    0
  );

  const kpis = [
    { label: "درس‌های تکمیل‌شده", value: toFa(totalCompletedLessons), chip: "+۴" },
    { label: "دوره‌های فعال", value: toFa(activeCourses.length), chip: "در حال یادگیری" },
    { label: "گواهی‌های کسب‌شده", value: toFa(certificates.length), chip: "A+", dark: true },
    { label: "امتیاز رتبه‌بندی", value: toFa(user.level?.points || 2480) },
  ];

  return (
    <section id="panel">
      <PanelLayout page="dashboard" onNavigate={onNavigate}>
        {/* ---------- Greeting ---------- */}
        <h1 className="pnl-h1">
          <span className="w" style={{ transform: "rotate(-1.5deg)", display: "inline-block" }}>سلام</span>{" "}
          <span className="w accent" style={{ transform: "rotate(1.5deg)", display: "inline-block" }}>{user.firstName}</span>
        </h1>
        <p className="pnl-sub">{user.greeting}</p>

        {/* ---------- Streak banner ---------- */}
        <div className="pnl-streak">
          <div>
            <h3>{toFa(streak.days)} روز پیاپی یادگیری</h3>
            <p>{streak.hint}</p>
            {!streak.todayRecorded ? (
              <button
                type="button"
                className="pnl-cbtn"
                style={{ marginTop: 10, fontSize: "13px", padding: "8px 16px", display: "inline-flex", alignItems: "center", gap: 6 }}
                onClick={handleRecordStreak}
              >
                <Flame size={16} />
                <span>ثبت مطالعه امروز (+۱۰۰ امتیاز)</span>
              </button>
            ) : (
              <span
                style={{
                  display: "inline-flex",
                  alignItems: "center",
                  gap: 4,
                  marginTop: 10,
                  fontSize: "12.5px",
                  fontWeight: 900,
                  color: "var(--teal-dark)",
                  background: "var(--teal-light)",
                  border: "1.5px solid var(--ink)",
                  padding: "4px 10px",
                  borderRadius: "6px 0 6px 0",
                }}
              >
                <CheckCircle2 size={15} />
                <span>مطالعه امروز ثبت شد</span>
              </span>
            )}
          </div>
          <div className="pnl-flames" aria-hidden="true">
            {streak.week.map((d, i) => (
              <div key={i} className={`pnl-flame${d.on ? "" : " off"}`}>{toFa(i + 1)}</div>
            ))}
          </div>
        </div>

        {/* ---------- KPIs ---------- */}
        <div className="pnl-kpis">
          {kpis.map((k) => (
            <div key={k.label} className={`pnl-kpi${k.dark ? " dark" : ""}`}>
              <div className="lbl">
                {k.label}
                {k.chip && <span className="chip">{k.chip}</span>}
              </div>
              <div className="v">{k.value}</div>
            </div>
          ))}
        </div>

        {/* ---------- Learning + Schedule ---------- */}
        <div className="pnl-grid">
          <div className="pnl-panel">
            <h4>
              ادامهٔ یادگیری
              <button
                type="button"
                className="pnl-link-btn"
                onClick={() => onNavigate("courses")}
                style={{ background: "none", border: "none", cursor: "pointer", color: "var(--navy)", fontWeight: 800, fontFamily: "inherit", display: "inline-flex", alignItems: "center", gap: 4 }}
              >
                <span>مشاهده همه</span>
                <ArrowLeft size={14} />
              </button>
            </h4>
            {activeCourses.slice(0, 4).map((c) => (
              <div className="pnl-course" key={c.id}>
                <div className="pnl-thumb">
                  <img src={c.pattern} alt="" aria-hidden="true" />
                  <PlayGlyph />
                </div>
                <div>
                  <b>{c.title}</b>
                  <div className="m">{c.next || c.sessions}</div>
                  <div className="pnl-prog">
                    <i style={{ width: `${c.progress}%` }} />
                  </div>
                </div>
                <button
                  className={`pnl-cbtn${c.progress === 100 ? " ok" : ""}`}
                  onClick={() => onNavigate("courses")}
                >
                  {c.progress === 100 ? "تکمیل شد" : "ادامه"}
                </button>
              </div>
            ))}
            {activeCourses.length === 0 && (
              <div style={{ textAlign: "center", padding: "20px 0", color: "var(--ink-subtle)", fontSize: "14px", fontWeight: 700 }}>
                تمامی دوره‌های شما تکمیل شده‌اند!
                <button
                  className="pnl-cbtn wide"
                  style={{ marginTop: 12 }}
                  onClick={() => { window.location.hash = "courses-index"; }}
                >
                  مشاهده کاتالوگ و ثبت‌نام در دوره جدید
                </button>
              </div>
            )}
          </div>

          <div className="pnl-panel">
            <h4>
              برنامه و رویدادهای من
              <button
                type="button"
                className="pnl-link-btn"
                onClick={() => onNavigate("events")}
                style={{ background: "none", border: "none", cursor: "pointer", color: "var(--navy)", fontWeight: 800, fontFamily: "inherit", display: "inline-flex", alignItems: "center", gap: 4 }}
              >
                <span>تقویم کامل</span>
                <ArrowLeft size={14} />
              </button>
            </h4>
            <div className="pnl-sched">
              {registeredEvents.map((ev) => (
                <div key={ev.id} className={`pnl-ev${ev.featured ? " today" : ""}`}>
                  <div className="day">
                    <b>{ev.day}</b>
                    <span>{ev.month}</span>
                  </div>
                  <div className="info">
                    <b>{ev.title}</b>
                    <span>{ev.time} · {ev.host}</span>
                  </div>
                </div>
              ))}
            {registeredEvents.length === 0 && (
                <div style={{ padding: "16px", textAlign: "center", color: "var(--ink-subtle)", fontSize: "13.5px" }}>
                  هنوز در رویدادی ثبت‌نام نکرده‌اید.
                  <button className="pnl-cbtn ghost" style={{ marginTop: 10, width: "100%" }} onClick={() => onNavigate("events")}>
                    مشاهده رویدادها و وبینارها
                  </button>
                </div>
              )}
            </div>
          </div>
        </div>

        {/* سوابق تراکنش‌ها و سفارش‌های دوره */}
        {store.orders && store.orders.length > 0 && (
          <div className="pnl-panel" style={{ marginTop: 24 }}>
            <h4>
              سوابق پرداخت و فاکتورهای دوره‌ها
              <span className="pnl-pill">{toFa(store.orders.length)} سفارش</span>
            </h4>
            <div style={{ display: "flex", flexDirection: "column", gap: 10, marginTop: 12 }}>
              {store.orders.map((ord) => (
                <div
                  key={ord.id}
                  style={{
                    display: "flex",
                    justifyContent: "space-between",
                    alignItems: "center",
                    flexWrap: "wrap",
                    gap: 10,
                    padding: "12px 16px",
                    background: "#f8fafc",
                    border: "1.5px solid var(--ink)",
                    borderRadius: "8px 0 8px 0",
                    fontSize: "13px",
                  }}
                >
                  <div>
                    <b style={{ color: "var(--ink)" }}>{ord.courseTitle}</b>
                    <div style={{ fontSize: "11.5px", color: "var(--ink-muted)", marginTop: 2 }}>
                      شناسه: {ord.id} · تاریخ: {ord.createdAt} · درگاه: {ord.gateway}
                    </div>
                  </div>
                  <div style={{ display: "flex", alignItems: "center", gap: 12 }}>
                    <span style={{ fontWeight: 800, color: "var(--accent)" }}>
                      {ord.paidAmount ? ord.paidAmount.toLocaleString("fa-IR") + " تومان" : "رایگان"}
                    </span>
                    <span
                      style={{
                        padding: "3px 8px",
                        background: ord.status === "paid" ? "var(--teal-light)" : "#fde8e8",
                        color: ord.status === "paid" ? "var(--teal-dark)" : "#9b1c1c",
                        border: "1px solid var(--ink)",
                        borderRadius: "4px",
                        fontSize: "11px",
                        fontWeight: 900,
                      }}
                    >
                      {ord.status === "paid" ? `پرداخت موفق (کد: ${ord.trackingCode || "تایید شده"})` : "در انتظار پرداخت"}
                    </span>
                  </div>
                </div>
              ))}
            </div>
          </div>
        )}
      </PanelLayout>
    </section>
  );
}
