/* بج نحوه برگزاری دوره (حضوری / غیر حضوری) */
const CourseModeBadge = ({ mode, className = "" }) => {
  const isOnline = mode === "online";
  return (
    <span className={`course-mode-badge ${isOnline ? "online" : "in-person"} ${className}`}>
      {isOnline ? <Monitor size={12} strokeWidth={2.4} /> : <MapPin size={12} strokeWidth={2.4} />}
      <span>{isOnline ? "غیر حضوری" : "حضوری"}</span>
    </span>
  );
};

/* دکمهٔ آیکون سیو / نشان کردن کارت دوره */
const CourseSaveButton = ({ slug, store, className = "" }) => {
  const isLoggedIn = Boolean(store?.auth?.isLoggedIn);
  const isSaved = isLoggedIn && isWishlisted(slug, store);
  return (
    <button
      type="button"
      className={`course-card-save-btn ${isSaved ? "is-saved" : ""} ${className}`}
      onClick={(e) => {
        e.preventDefault();
        e.stopPropagation();
        if (!isLoggedIn) {
          window.dispatchEvent(
            new CustomEvent("rokad_auth_required", {
              detail: {
                message: "برای ذخیره دوره‌ها، لطفاً ابتدا در کالج ثبت‌نام کنید.",
                action: "register",
              },
            })
          );
          return;
        }
        toggleWishlist(slug);
      }}
      aria-label={isLoggedIn ? (isSaved ? "حذف از نشان‌شده‌ها" : "نشان کردن دوره") : "برای ذخیره دوره، ثبت‌نام کنید"}
      title={isLoggedIn ? (isSaved ? "حذف از نشان‌شده‌ها" : "نشان کردن دوره") : "برای ذخیره دوره، ابتدا ثبت‌نام کنید"}
    >
      <Bookmark size={15} fill={isSaved ? "currentColor" : "none"} stroke="currentColor" strokeWidth={2.2} />
    </button>
  );
};

/* مپ کردن دوره‌ها به اسلاگ تک‌دوره */
const getCourseSlug = (title = "", mode = "") => {
  const t = title.toLowerCase();
  const isInPerson = mode === "in-person" || mode === "حضوری";
  if (isInPerson) {
    if (t.includes("react") || t.includes("next.js") || t.includes("فرانت")) return "react-bootcamp";
    if (t.includes("ux") || t.includes("ui") || t.includes("فیگما")) return "ux-bootcamp";
    if (t.includes("گرافیک") || t.includes("فتوشاپ")) return "graphic-bootcamp";
    if (t.includes("mba") || t.includes("کارآفرینی") || t.includes("کسب‌وکار")) return "mba-bootcamp";
    if (t.includes("رهبری") || t.includes("مدیریت")) return "leadership-bootcamp";
    if (t.includes("فروش") || t.includes("مذاکره")) return "sales-bootcamp";
    if (t.includes("ielts") || t.includes("آیلتس") || t.includes("مکالمه") || t.includes("انگلیسی")) return "ielts-bootcamp";
    if (t.includes("devops") || t.includes("docker")) return "devops-bootcamp";
    return "react-bootcamp";
  }
  if (t.includes("react") || t.includes("next.js") || t.includes("فرانت")) return "frontend-react";
  if (t.includes("python") || t.includes("ai") || t.includes("ماشین") || t.includes("داده")) return "python-ai";
  if (t.includes("node") || t.includes("api") || t.includes("بک‌اند")) return "frontend-react";
  if (t.includes("mba") || t.includes("کارآفرینی") || t.includes("رهبری") || t.includes("مدیریت")) return "mba-business";
  if (t.includes("مارکتینگ") || t.includes("سئو") || t.includes("دیجیتال")) return "seo-pro";
  if (t.includes("ielts") || t.includes("آیلتس") || t.includes("مکالمه") || t.includes("انگلیسی") || t.includes("business english")) return "ielts-mastery";
  if (t.includes("وردپرس")) return "wordpress-pro";
  return "ui-ux";
};

