/* هوک اسکرول افقی و قابلیت Drag با ماوس دقیقاً مطابق تک‌صفحه دپارتمان‌ها */
function useHorizontalDragScroll() {
  const rowRef = useRef(null);
  const animRef = useRef(0);
  const modelRef = useRef("flip"); // flip = کروم/فایرفاکس (RTL منفی)، legacy = سافاری
  const [nav, setNav] = useState({ prev: false, next: true });
  const isDraggingRef = useRef(false);
  const dragInfoRef = useRef({ startX: 0, scrollLeft: 0, hasMoved: false });

  const metrics = () => {
    const el = rowRef.current;
    if (!el) return { max: 0, pos: 0 };
    const max = el.scrollWidth - el.clientWidth;
    const rtl = getComputedStyle(el).direction === "rtl";
    if (!rtl) return { max, pos: el.scrollLeft };
    return { max, pos: modelRef.current === "legacy" ? max - el.scrollLeft : -el.scrollLeft };
  };

  const update = () => {
    const el = rowRef.current;
    if (!el) return;
    const { max, pos } = metrics();
    setNav({ prev: pos > 4, next: max > 0 && max - pos > 4 });
  };

  useEffect(() => {
    const el = rowRef.current;
    if (!el) return;
    const max = el.scrollWidth - el.clientWidth;
    if (getComputedStyle(el).direction === "rtl" && max > 0) {
      modelRef.current = Math.abs(el.scrollLeft) < max / 2 ? "flip" : "legacy";
    }
    update();
    el.addEventListener("scroll", update, { passive: true });
    window.addEventListener("resize", update);

    const onMouseDown = (e) => {
      if (e.button !== 0) return;
      isDraggingRef.current = true;
      dragInfoRef.current = {
        startX: e.pageX - el.offsetLeft,
        scrollLeft: el.scrollLeft,
        hasMoved: false,
      };
      el.classList.add("is-dragging");
    };

    const onMouseMove = (e) => {
      if (!isDraggingRef.current) return;
      const x = e.pageX - el.offsetLeft;
      const delta = x - dragInfoRef.current.startX;
      if (Math.abs(delta) > 6) {
        dragInfoRef.current.hasMoved = true;
        e.preventDefault();
      }
      if (dragInfoRef.current.hasMoved) {
        const walk = delta * 1.25;
        el.scrollLeft = dragInfoRef.current.scrollLeft - walk;
      }
    };

    const onMouseUp = () => {
      if (!isDraggingRef.current) return;
      isDraggingRef.current = false;
      el.classList.remove("is-dragging");
      setTimeout(() => {
        if (dragInfoRef.current) {
          dragInfoRef.current.hasMoved = false;
        }
      }, 80);
    };

    el.addEventListener("mousedown", onMouseDown);
    window.addEventListener("mousemove", onMouseMove);
    window.addEventListener("mouseup", onMouseUp);

    return () => {
      cancelAnimationFrame(animRef.current);
      el.removeEventListener("scroll", update);
      window.removeEventListener("resize", update);
      el.removeEventListener("mousedown", onMouseDown);
      window.removeEventListener("mousemove", onMouseMove);
      window.removeEventListener("mouseup", onMouseUp);
    };
  }, []);

  const scroll = (toNext) => {
    const el = rowRef.current;
    if (!el) return;
    cancelAnimationFrame(animRef.current);
    const rtl = getComputedStyle(el).direction === "rtl";
    const dir = rtl ? (toNext ? -1 : 1) : (toNext ? 1 : -1);
    const from = el.scrollLeft;
    const to = from + dir * el.clientWidth * 0.75;
    const t0 = performance.now();
    const ease = (p) => 1 - Math.pow(1 - p, 3);
    const step = (now) => {
      const p = Math.min(1, (now - t0) / 450);
      el.scrollLeft = from + (to - from) * ease(p);
      if (p < 1) animRef.current = requestAnimationFrame(step);
    };
    animRef.current = requestAnimationFrame(step);
  };

  return { rowRef, nav, update, scroll };
}

export default function CoursesPage() {
  const [store, setStore] = useState(getPanelStore);
  const instScroll = useHorizontalDragScroll();

  useEffect(() => {
    const handleStoreChange = (e) => {
      setStore(e.detail || getPanelStore());
    };
    window.addEventListener("rokad_panel_store_changed", handleStoreChange);
    return () => window.removeEventListener("rokad_panel_store_changed", handleStoreChange);
  }, []);

  const displayedSuggestedGroups = Object.values(SUGGESTED_BY_DEPT);

  return (
    <div className="ch-page">
      {/* ---------- هدر و هیرو صفحه ---------- */}
      <header className="ch-hero">
        <PatternLayer rotate={0} />
        <div className="ch-hero-inner">
          <nav className="ch-crumb" aria-label="مسیر راهنما">
            <a href="#">خانه</a>
            <span className="ch-crumb-sep">›</span>
            <span className="ch-crumb-cur">دوره‌ها و دپارتمان‌ها</span>
          </nav>

          <div className="ch-hero-badge">
            <Sparkles size={14} />
            <span>کاتالوگ جامع دوره‌های کالج رکاد</span>
          </div>

          <h1 className="ch-hero-title">
            مسیر حرفه‌ای خود را با{" "}
            <span className="ch-marker">دوره‌های تخصصی</span> کالج بسازید
          </h1>

          <p className="ch-hero-desc">
            مجموعه‌ای منتخب از کاربردی‌ترین دوره‌های پروژه‌محور در دپارتمان‌های فناوری اطلاعات، کسب‌وکار و زبان‌های خارجی، تدریس‌شده توسط برجسته‌ترین اساتید و مدیران صنعت.
          </p>

          <div className="ch-stats">
            <div className="ch-stat-pill">
              <BookOpen size={16} />
              <span>بیش از <strong>۵۰+</strong> دوره تخصصی</span>
            </div>
            <div className="ch-stat-pill">
              <Users size={16} />
              <span>بیش از <strong>۱۲٬۰۰۰+</strong> هنرجوی فعال</span>
            </div>
            <div className="ch-stat-pill">
              <Award size={16} />
              <span><strong>۹۲٪</strong> نرخ موفقیت در اشتغال</span>
            </div>
          </div>
        </div>
      </header>

      <div className="ch-container">
        {/* ============================================================
            سکشن ۱: دوره‌های منتخب و برگزیدهٔ هر دپارتمان
            ============================================================ */}
        <section className="ch-sec" id="ch-flagships">
          <div className="ch-sec-head">
            <div className="ch-sec-title-wrap">
              <span className="ch-sec-tag">
                <Award size={13} /> دوره‌های منتخب و برگزیده
              </span>
              <h2 className="ch-sec-title">دوره‌های منتخب و برتر هر دپارتمان</h2>
            </div>
          </div>

          <div className="ch-flagships">
            {FLAGSHIP_COURSES.map((f) => {
              const FlagIcon = f.icon;
              return (
                <article key={f.deptId} className={`ch-flag-card ${f.themeClass}`}>
                  {/* بخش بصری چپ کارت */}
                  <div className="ch-flag-visual">
                    <img src={f.pattern} alt="" className="ch-flag-pattern" aria-hidden="true" />
                    <CourseSaveButton slug={f.slug} store={store} className="ch-flag-save-btn" />
                    <span className="ch-flag-dept-chip">دپارتمان {f.deptName}</span>
                    <div className="ch-flag-icon-wrap">
                      <FlagIcon size={44} style={{ color: "var(--ink)" }} />
                    </div>
                    <span className="ch-flag-badge">
                      <Sparkles size={12} />
                      {f.badge}
                    </span>
                  </div>

                  {/* بخش محتوا و اطلاعات */}
                  <div className="ch-flag-content">
                    <div className="ch-flag-top">
                      <div className="ch-flag-meta-row">
                        <div className="ch-flag-meta-info">
                          <span>مدرس دوره: <strong>{f.inst}</strong></span>
                          <span>•</span>
                          <span style={{ display: "inline-flex", alignItems: "center", gap: 4 }}>
                            <Star size={14} fill="#f5a623" color="#f5a623" />
                            <strong>{f.rating}</strong>
                          </span>
                        </div>
                        <CourseModeBadge mode={f.mode} />
                      </div>

                      <h3 className="ch-flag-title">{f.title}</h3>
                      <p className="ch-flag-desc">{f.desc}</p>

                      <div className="ch-flag-stats-row">
                        <span className="ch-flag-pill">
                          <Clock size={13} />
                          {f.hours}
                        </span>
                        <span className="ch-flag-pill">
                          <Users size={13} />
                          {f.students}
                        </span>
                        <span className="ch-flag-pill">
                          <CheckCircle2 size={13} />
                          پروژه‌محور با گواهی معتبر
                        </span>
                      </div>
                    </div>

                    <div className="ch-flag-actions">
                      <div className="ch-flag-price-block">
                        {f.old && <s>{f.old}</s>}
                        <b>{f.price}</b>
                      </div>

                      <div className="ch-flag-btn-group">
                        <a href={`#course/${f.slug}`} className="ch-btn-view-course">
                          <span>مشاهده سرفصل دوره</span>
                          <ArrowLeft size={14} />
                        </a>
                        <a href={f.deptHref} className="ch-btn-dept-gateway">
                          <span>{f.deptBtnText}</span>
                          <ChevronLeft size={16} />
                        </a>
                      </div>
                    </div>
                  </div>
                </article>
              );
            })}
          </div>
        </section>

        {/* ============================================================
            سکشن ۲: دوره‌های پیشنهادی از هر دپارتمان
            ============================================================ */}
        <section className="ch-sec" id="ch-suggested">
          <div className="ch-sec-head">
            <div className="ch-sec-title-wrap">
              <span className="ch-sec-tag">
                <Compass size={13} /> دوره‌های پیشنهادی
              </span>
              <h2 className="ch-sec-title">دوره‌های پیشنهادی برای شروع هر مسیر</h2>
            </div>
          </div>

          {/* گروه‌های دوره‌های پیشنهادی هر دپارتمان */}
          {displayedSuggestedGroups.map((group) => {
            const DeptIcon = DEPT_ICONS[group.deptId] || Code;
            return (
              <div key={group.deptId} style={{ marginBottom: 68 }}>
                <div className="ch-suggested-dept-header">
                  <span
                    style={{
                      display: "inline-flex",
                      alignItems: "center",
                      gap: 6,
                      background: group.badgeBg,
                      color: group.badgeColor,
                      border: "2px solid var(--ink)",
                      borderRadius: "8px",
                      padding: "4px 12px",
                      fontSize: "13px",
                      fontWeight: "900",
                      boxShadow: "2px 2px 0 var(--ink)",
                    }}
                  >
                    <DeptIcon size={14} />
                    دپارتمان {group.deptName}
                  </span>
                  <a
                    href={`#dept/${group.deptId}`}
                    className="ch-dept-more-link"
                  >
                    <span>مشاهده همه دوره‌های {group.deptName}</span>
                    <span className="ch-dept-more-arrow" aria-hidden="true">
                      <ChevronLeft size={15} strokeWidth={2.8} />
                    </span>
                  </a>
                </div>

                <div className="ch-grid-3">
                  {group.courses.map((c) => (
                    <a
                      key={c.id}
                      href={`#course/${c.slug}`}
                      className="ch-card"
                      data-dept={group.deptId}
                    >
                      <div className="ch-card-cover" style={{ background: group.badgeBg }}>
                        <img src={group.pattern} alt="" className="ch-cover-pat" aria-hidden="true" />
                        <span className={`ch-card-tag ${c.tagType}`}>{c.tag}</span>
                        <CourseSaveButton slug={c.slug} store={store} />
                        <DeptIcon size={34} style={{ color: group.badgeColor, position: "relative", zIndex: 1 }} />
                      </div>

                      <div className="ch-card-body">
                        <div className="ch-card-badges-row">
                          <span
                            className="ch-card-dept-badge"
                            style={{ background: group.badgeBg, color: group.badgeColor }}
                          >
                            {c.cat}
                          </span>
                          <CourseModeBadge mode={c.mode} />
                        </div>

                        <h3 className="ch-card-title">{c.title}</h3>

                        <div className="ch-card-inst">
                          <span className="ch-card-av">{c.inst.charAt(0)}</span>
                          <span>مدرس: {c.inst}</span>
                        </div>

                        <div className="ch-card-meta">
                          <span className="ch-card-meta-item ch-rate">
                            <Star size={13} fill="#f5a623" color="#f5a623" />
                            {c.rating}
                          </span>
                          <span className="ch-card-meta-item">
                            <Clock size={13} />
                            {c.hours}
                          </span>
                          <span className="ch-card-meta-item">
                            <Users size={13} />
                            {c.students}
                          </span>
                        </div>

                        <div className="ch-card-foot">
                          <div className="ch-card-price">
                            {c.old && <s>{c.old}</s>}
                            <b>{c.price}</b>
                          </div>
                          <span className="ch-card-btn">
                            <span>مشاهده</span>
                            <ArrowLeft size={13} />
                          </span>
                        </div>
                      </div>
                    </a>
                  ))}
                </div>
              </div>
            );
          })}
        </section>

        {/* ============================================================
            سکشن ۳: اساتید برجستهٔ کالج رکاد (تک‌ردیفه و اسکرولی)
            ============================================================ */}
        <section className="ch-sec" id="ch-instructors">
          <div className="ch-sec-head">
            <div className="ch-sec-title-wrap">
              <span className="ch-sec-tag">
                <Users size={13} /> منتورها و مربیان صنعت
              </span>
              <h2 className="ch-sec-title">اساتید و مربیان برجستهٔ کالج رکاد</h2>
            </div>
            <div className="ch-inst-nav-btns" aria-label="هدایت اسلاید اساتید">
              <button
                type="button"
                className="ch-inst-nav-btn"
                disabled={!instScroll.nav.prev}
                onClick={() => instScroll.scroll(false)}
                aria-label="اساتید قبلی"
                title="قبلی"
              >
                <ChevronRight size={18} strokeWidth={2.5} />
              </button>
              <button
                type="button"
                className="ch-inst-nav-btn"
                disabled={!instScroll.nav.next}
                onClick={() => instScroll.scroll(true)}
                aria-label="اساتید بعدی"
                title="بعدی"
              >
                <ChevronLeft size={18} strokeWidth={2.5} />
              </button>
            </div>
          </div>

          <div className="ch-inst-track-wrap">
            <div className="ch-inst-track" ref={instScroll.rowRef}>
              {TOP_INSTRUCTORS.map((inst) => (
                <div key={inst.name} className="ch-inst-card">
                  {/* نیمه بالایی با رنگ سازمانی کالج و پترن */}
                  <div className="ch-inst-cover">
                    <img
                      src="/assets/Pattern/layout-pattern.png"
                      alt=""
                      className="ch-inst-cover-pattern"
                      aria-hidden="true"
                    />
                    <span className="ch-inst-dept-badge">
                      {inst.dept}
                    </span>
                  </div>

                  {/* عکس پروفایل در بالا و وسط، روی مرز کاور و بدنه */}
                  <div className="ch-inst-av-centered-wrap">
                    <div className="ch-inst-av-box">
                      <img
                        src={inst.avatar}
                        alt={inst.name}
                        className="ch-inst-img"
                        loading="lazy"
                        onError={(e) => {
                          e.currentTarget.style.display = "none";
                        }}
                      />
                      <div className="ch-inst-fallback-av">
                        {inst.initial}
                      </div>
                    </div>
                  </div>

                  {/* توضیحات و مشخصات در بخش پایین */}
                  <div className="ch-inst-body-centered">
                    <h3 className="ch-inst-name">{inst.name}</h3>
                    <div className="ch-inst-role">{inst.role}</div>
                    <p className="ch-inst-bio">{inst.bio}</p>

                    <div className="ch-inst-stats">
                      <span className="ch-inst-stat-item">
                        <BookOpen size={13} />
                        <span>{inst.courses}</span>
                      </span>
                      <span className="ch-inst-stat-item">
                        <Users size={13} />
                        <span>{inst.students} هنرجو</span>
                      </span>
                      <span className="ch-inst-stat-item ch-rate">
                        <Star size={13} fill="#f5a623" color="#f5a623" />
                        <span>{inst.rating}</span>
                      </span>
                    </div>
                  </div>
                </div>
              ))}
            </div>
          </div>
        </section>
      </div>
    </div>
  );
}