/* ============================================================
   تک‌صفحهٔ اختصاصی دوره‌های حضوری: CourseSingleInPerson
   - سکشن افقی بالا: تصویر بزرگ دوره + مشخصات + قیمت و دکمه ثبت‌نام
   - حذف بخش‌های اضافه (امکانات کمپوس و برنامه زمانی)
   - تب‌های متمرکز: سرفصل‌های کارگاه | موقعیت و دسترسی | مدرس دوره
   ============================================================ */
import { useState, useEffect } from "react";
import "./course.css";
import "./courseInPerson.css";
import PatternLayer from "../../components/PatternLayer";
import { getPanelStore, toggleWishlist } from "../../data/panelStore.js";
import { isEnrolledIn, isWishlisted as checkWishlisted } from "../../data/selectors.js";
import CheckoutModal from "../Checkout/CheckoutModal.jsx";
import {
  Building2,
  Calendar,
  Clock,
  Award,
  Train,
  Car,
  Phone,
  ShieldCheck,
  CheckCircle2,
  Check,
  ArrowLeft,
  Bookmark,
  MapPin,
  ExternalLink,
  ChevronDown,
  FileText,
  BookOpen,
  UserCheck,
} from "lucide-react";

const FA = "۰۱۲۳۴۵۶۷۸۹";
const toFa = (n) => String(n ?? "").replace(/\d/g, (d) => FA[d]);

export default function CourseSingleInPerson({ course, slug }) {
  const [store, setStore] = useState(getPanelStore);
  const [openSprint, setOpenSprint] = useState(0);
  const [checkoutOpen, setCheckoutOpen] = useState(false);

  useEffect(() => {
    const handleStoreChange = (e) => {
      setStore(e.detail || getPanelStore());
    };
    window.addEventListener("rokad_panel_store_changed", handleStoreChange);
    return () => window.removeEventListener("rokad_panel_store_changed", handleStoreChange);
  }, []);

  const courseSlug = course.slug || slug;
  const isLoggedIn = Boolean(store?.auth?.isLoggedIn);
  const isEnrolled = isEnrolledIn(courseSlug, store);
  const isWished = isLoggedIn && checkWishlisted(courseSlug, store);

  const venue = course.venue || {
    name: "کمپوس مرکزی کالج رکاد",
    address: "تهران، میدان آزادی، بلوار اکبری، جنب ایستگاه مترو، پلاک ۲۴، طبقه ۳",
    metro: "۲ دقیقه پیاده‌روی از ایستگاه مترو میدان آزادی (خط ۴)",
    parking: "دارای پارکینگ اختصاصی برای هنرجویان",
    room: "سالن کارگاهی آلفا",
  };

  const schedule = course.schedule || {
    days: "شنبه و چهارشنبه",
    hours: "۱۶:۰۰ الی ۲۰:۰۰",
    totalWeeks: "۱۰ هفته",
    totalHours: "۸۰ ساعت کارگاهی + ۴۰ ساعت منتورینگ",
    startDate: course.startDate || "۱۵ مهر ۱۴۰۴",
  };

  const cleanDays = (schedule.days || "").replace(/\s*\(.*?\)/g, "").trim();
  const cleanHours = (schedule.hours || "").replace(/\s*\(.*?\)/g, "").trim();
  const cleanRoom = (venue.room || "سالن کارگاهی آلفا").replace(/\s*\(.*?\)/g, "").trim();

  const capacity = course.capacity || {
    total: 18,
    registered: 14,
    remaining: 4,
    pct: 78,
  };

  const sprints = course.sprints || [
    {
      n: "۰۱",
      weeks: "هفته ۱ و ۲",
      title: "راه‌اندازی محیط کار تیمی و زیرساخت حرفه‌ای",
      desc: "پیکربندی ورک‌استیشن، گیت تیمی، استانداردهای کدنویسی تمیز و پیاده‌سازی نخستین تسک عملیاتی کارگاه.",
      output: "ریپازیتوری تیمی استاندارد و اجرای نخستین سناریو",
    },
    {
      n: "۰۲",
      weeks: "هفته ۳ تا ۵",
      title: "معماری عمیق، حل چالش‌های واقعی و کد ریویو زنده",
      desc: "پیاده‌سازی معماری ماژولار با هدایت استاد و بررسی خط‌به‌خط پروژه‌ها روی پروژکتور سالن کارگاه.",
      output: "پیاده‌سازی هسته عملیاتی پروژه تیمی",
    },
    {
      n: "۰۳",
      weeks: "هفته ۶ و ۷",
      title: "هکاتون حضوری و شبیه‌سازی اسپرینت اسکرام شرکتی",
      desc: "شبیه‌سازی یک اسپرینت فشرده شرکتی، مواجهه با باگ‌های نامنتظره و استقرار روی سرور واقعی.",
      output: "نسخه قابل اتکا و آماده تحویل محصول (Production-Ready)",
    },
    {
      n: "۰۴",
      weeks: "هفته ۸ تا ۱۰",
      title: "ارائه در Demo Day، ساخت رزومه و آمادگی مصاحبه",
      desc: "پرزنت محصول در حضور مدیران فنی شرکت‌های پارتنر کالج رکاد و شبیه‌سازی مصاحبه‌های استخدامی.",
      output: "پورتفولیوی اختصاصی و معرفی رزومه به شرکت‌های همکار",
    },
  ];

  const teacher = course.teacher || {
    name: "مهندس آرش تهرانی",
    role: "مدرس ارشد و سرپرست کارگاه حضوری",
    bio: "بیش از ۱۰ سال سابقه هدایت تیم‌های فنی در شرکت‌های بزرگ فناوری و راهبری بیش از ۶۰۰ متخصص تا ورود به بازار کار.",
    initial: "آ.ت",
  };

  const handleBookmarkClick = () => {
    if (!isLoggedIn) {
      window.dispatchEvent(
        new CustomEvent("rokad_auth_required", {
          detail: {
            message: "برای ذخیره دوره‌ها، لطفاً ابتدا در کالج ثبت‌نام کنید.",
            action: "register",
          },
        })
      );
      return;
    }
    toggleWishlist(courseSlug);
  };

  return (
    <main className="cs-page cs-inperson-wrapper" id="course">
      <PatternLayer rotate={0} />

      {/* ---------- Topbar: مسیر صفحه و بازگشت ---------- */}
      <div className="cs-topbar container">
        <a href="#courses-index" className="cs-back">
          <ArrowLeft size={14} style={{ transform: "rotate(180deg)" }} />
          <span>همهٔ دوره‌ها</span>
        </a>

        <nav className="cs-crumbs" aria-label="مسیر دوره">
          <a href="#courses-index">دوره‌ها</a>
          <span className="sep">›</span>
          {course.departmentFa && (
            <>
              <a href={`#courses-index/${course.department || "all"}`}>{course.departmentFa}</a>
              <span className="sep">›</span>
            </>
          )}
          <b>{course.title}</b>
        </nav>

        <div className="cs-inperson-top-actions">
          <div className="cs-inperson-top-badge">
            <MapPin size={12} strokeWidth={2.5} />
            <span>کارگاه حضوری</span>
          </div>

          <button
            type="button"
            className={`cs-inperson-top-save-btn ${isWished ? "is-saved" : ""}`}
            onClick={handleBookmarkClick}
            aria-label={isLoggedIn ? (isWished ? "حذف از نشان‌شده‌ها" : "نشان کردن دوره") : "برای ذخیره دوره، ابتدا ثبت‌نام کنید"}
            title={isLoggedIn ? (isWished ? "حذف از نشان‌شده‌ها" : "نشان کردن دوره") : "برای ذخیره دوره، ابتدا ثبت‌نام کنید"}
          >
            <Bookmark size={15} fill={isWished ? "currentColor" : "none"} stroke="currentColor" strokeWidth={2.2} />
          </button>
        </div>
      </div>

      <div className="container">
        {/* ================= سکشن افقی بالا (Hero افقی با تصویر و دکمه‌ها) ================= */}
        <div className="cs-ip-hero-card">
          <div className="cs-ip-hero-grid">
            {/* ستون تصویر دوره (سمت راست در چیدمان RTL) */}
            <div className="cs-ip-hero-media">
              <img
                src={course.pattern || "/assets/StatCard/blue.png"}
                alt={course.title}
                className="cs-ip-hero-img"
              />
              <span className="cs-ip-hero-tag">
                <MapPin size={12} strokeWidth={2.5} />
                <span>کمپوس آزادی</span>
              </span>
            </div>

            {/* ستون محتوا + قیمت + دکمه‌های اقدام (افقی در کنار تصویر) */}
            <div className="cs-ip-hero-content">
              <div className="cs-ip-hero-header-info">
                <div className="cs-ip-hero-topline">
                  <span className="cs-ip-dept-tag">{course.departmentFa || "دوره حضوری"}</span>
                </div>

                <h1 className="cs-ip-hero-title">{course.title}</h1>

                {/* مشخصات کلیدی تک‌خطی */}
                <div className="cs-ip-hero-pills">
                  <span className="ip-pill">
                    <Calendar size={13} strokeWidth={2.2} />
                    <span>شروع: {schedule.startDate}</span>
                  </span>
                  <span className="ip-pill">
                    <Clock size={13} strokeWidth={2.2} />
                    <span>طول دوره: {schedule.totalWeeks}</span>
                  </span>
                </div>
              </div>

              {/* باکس قیمت، ظرفیت و دکمه ثبت‌نام در هیرو */}
              <div className="cs-ip-hero-actions-bar">
                <div className="cs-ip-price-col">
                  <div className="cs-ip-price-row">
                    {course.oldPrice && <span className="old-price">{course.oldPrice}</span>}
                    <b className="main-price">{course.price}</b>
                    <span className="cur">تومان</span>
                    {course.discount && <span className="cs-discount-tag">{course.discount}</span>}
                  </div>

                  <div className="cs-ip-seat-alert">
                    <span className="seat-dot" />
                    <span>ظرفیت باقیمانده: فقط {toFa(capacity.remaining)} صندلی</span>
                  </div>
                </div>

                <div className="cs-ip-btns-row">
                  {isEnrolled ? (
                    <button
                      type="button"
                      className="cs-ip-btn-main enrolled"
                      onClick={() => { window.location.hash = "panel/courses"; }}
                    >
                      <CheckCircle2 size={16} />
                      <span>ورود به کلاس (ثبت‌نام شده)</span>
                    </button>
                  ) : (
                    <button
                      type="button"
                      className="cs-ip-btn-main"
                      onClick={() => setCheckoutOpen(true)}
                    >
                      <span>ثبت‌نام و رزرو صندلی</span>
                      <ArrowLeft size={16} />
                    </button>
                  )}

                  <button
                    type="button"
                    className="cs-ip-btn-sub"
                    onClick={() => { window.location.hash = "consult"; }}
                  >
                    <Phone size={14} />
                    <span>مشاوره تلفنی رایگان</span>
                  </button>
                </div>
              </div>

              {/* یادداشت گارانتی */}
              <div className="cs-ip-guarantee-strip">
                <ShieldCheck size={14} strokeWidth={2.4} />
                <span>گارانتی بازگشت ۱۰۰٪ شهریه تا پایان جلسه اول بدون قید و شرط</span>
              </div>
            </div>
          </div>
        </div>

        {/* ================= سکشن‌های محتوایی یکپارچه و متوالی (بدون تب) ================= */}
        <div className="cs-ip-sections-stack">
          {/* بخش ۱: درباره کارگاه حضوری */}
          <section className="cs-ip-section-card" id="about-workshop">
            <div className="cs-ip-sec-header">
              <div className="cs-ip-sec-header-right">
                <span className="cs-ip-sec-num">۰۱</span>
                <div className="cs-ip-sec-icon-box">
                  <FileText size={18} />
                </div>
                <div className="cs-ip-sec-titles">
                  <h2 className="cs-ip-sec-title">درباره این کارگاه حضوری</h2>
                  <span className="cs-ip-sec-sub">مشخصات، اهداف و رویکرد اجرایی دوره</span>
                </div>
              </div>
              <span className="cs-ip-sec-badge">معرفی کارگاه</span>
            </div>

            <div className="cs-ip-sec-body">
              <div className="cs-inperson-desc-panel">
                <div className="cs-desc-intro-card">
                  <p className="cs-desc-lede-text">{course.lede}</p>
                </div>
                {Array.isArray(course.description) && course.description.length > 0 && (
                  <div className="cs-desc-paragraphs">
                    {course.description.map((p, idx) => (
                      <p key={idx}>{p}</p>
                    ))}
                  </div>
                )}
              </div>
            </div>
          </section>

          {/* بخش ۲: سرفصل‌ها و اسپرینت‌های کارگاهی */}
          <section className="cs-ip-section-card" id="sprints-curriculum">
            <div className="cs-ip-sec-header">
              <div className="cs-ip-sec-header-right">
                <span className="cs-ip-sec-num">۰۲</span>
                <div className="cs-ip-sec-icon-box">
                  <BookOpen size={18} />
                </div>
                <div className="cs-ip-sec-titles">
                  <h2 className="cs-ip-sec-title">سرفصل‌ها و اسپرینت‌های کارگاهی</h2>
                  <span className="cs-ip-sec-sub">{toFa(sprints.length)} اسپرینت عملیاتی · {schedule.totalHours}</span>
                </div>
              </div>
              <span className="cs-ip-sec-badge highlight">مسیر یادگیری</span>
            </div>

            <div className="cs-ip-sec-body">
              <div className="cs-curriculum">
                <div className="cs-progress">
                  <b>{toFa(sprints.length)} اسپرینت کارگاهی · {schedule.totalHours}</b>
                  <div className="bar"><span style={{ width: "100%" }} /></div>
                </div>

                <div className="cs-chapters">
                  {sprints.map((sp, idx) => {
                    const isOpen = openSprint === idx;
                    return (
                      <div key={sp.n} className={`cs-ch ${isOpen ? "open" : ""}`}>
                        <button
                          type="button"
                          className="cs-ch-head"
                          onClick={() => setOpenSprint(isOpen ? -1 : idx)}
                        >
                          <span className="num">{toFa(sp.n)}</span>
                          <div className="info">
                            <b>{sp.title}</b>
                            <small>{sp.weeks}</small>
                          </div>
                          <span className="dur">{sp.output}</span>
                          <span className="chev">
                            <ChevronDown
                              size={16}
                              style={{
                                transform: isOpen ? "rotate(180deg)" : "none",
                                transition: "transform .2s ease",
                              }}
                            />
                          </span>
                        </button>
                        {isOpen && (
                          <div className="cs-inperson-sprint-detail">
                            <p>{sp.desc}</p>
                            <div className="cs-inperson-sprint-badge">
                              <Check size={13} strokeWidth={3} />
                              <span>خروجی مورد انتظار: {sp.output}</span>
                            </div>
                          </div>
                        )}
                      </div>
                    );
                  })}
                </div>
              </div>
            </div>
          </section>

          {/* بخش ۳: موقعیت و دسترسی کمپوس */}
          <section className="cs-ip-section-card" id="campus-location">
            <div className="cs-ip-sec-header">
              <div className="cs-ip-sec-header-right">
                <span className="cs-ip-sec-num">۰۳</span>
                <div className="cs-ip-sec-icon-box">
                  <MapPin size={18} />
                </div>
                <div className="cs-ip-sec-titles">
                  <h2 className="cs-ip-sec-title">زمان‌بندی، موقعیت و دسترسی کمپوس</h2>
                  <span className="cs-ip-sec-sub">روزهای برگزاری کارگاه، آدرس دقیق و راه‌های دسترسی</span>
                </div>
              </div>
              <span className="cs-ip-sec-badge">محل و زمان کارگاه</span>
            </div>

            <div className="cs-ip-sec-body">
              <div className="cs-inperson-location-panel">
                <div className="cs-inperson-location-grid">
                  {/* کارت آدرس و موقعیت مکانی (سمت راست در چیدمان RTL) */}
                  <div className="cs-inperson-address-card">
                    <div className="address-meta">
                      <strong>{venue.name}</strong>
                      <p>{venue.address}</p>
                    </div>
                    <div className="transit-items">
                      <div className="transit-it">
                        <Train size={16} />
                        <span>{venue.metro}</span>
                      </div>
                      <div className="transit-it">
                        <Car size={16} />
                        <span>{venue.parking}</span>
                      </div>
                    </div>
                  </div>

                  {/* کارت زمان‌بندی و روزهای برگزاری کارگاه (سمت چپ در چیدمان RTL) */}
                  <div className="cs-inperson-schedule-card">
                    <div className="cs-ip-sch-head">
                      <div className="cs-ip-sch-icon">
                        <Calendar size={18} />
                      </div>
                      <div>
                        <strong>برنامهٔ زمانی و روزهای کلاس</strong>
                        <span>جلسات هفتگی کارگاه در کمپوس</span>
                      </div>
                    </div>

                    <div className="cs-ip-sch-rows">
                      <div className="cs-ip-sch-row">
                        <span className="sch-label">روزهای برگزاری:</span>
                        <span className="sch-val highlight">{cleanDays}</span>
                      </div>
                      <div className="cs-ip-sch-row">
                        <span className="sch-label">ساعت کارگاه:</span>
                        <span className="sch-val">{cleanHours}</span>
                      </div>
                      <div className="cs-ip-sch-row">
                        <span className="sch-label">سالن اختصاصی:</span>
                        <span className="sch-val">{cleanRoom}</span>
                      </div>
                    </div>
                  </div>
                </div>

                <div className="cs-inperson-map-actions">
                  <a href="https://nshn.ir" target="_blank" rel="noreferrer" className="map-link-btn">
                    <span>مسیریابی با نشان</span>
                    <ExternalLink size={13} />
                  </a>
                  <a href="https://balad.ir" target="_blank" rel="noreferrer" className="map-link-btn">
                    <span>مسیریابی با بلد</span>
                    <ExternalLink size={13} />
                  </a>
                  <a href="https://maps.google.com" target="_blank" rel="noreferrer" className="map-link-btn">
                    <span>گوگل‌مپ</span>
                    <ExternalLink size={13} />
                  </a>
                </div>
              </div>
            </div>
          </section>

          {/* بخش ۴: مدرس و سرپرست کارگاه */}
          <section className="cs-ip-section-card" id="workshop-instructor">
            <div className="cs-ip-sec-header">
              <div className="cs-ip-sec-header-right">
                <span className="cs-ip-sec-num">۰۴</span>
                <div className="cs-ip-sec-icon-box">
                  <UserCheck size={18} />
                </div>
                <div className="cs-ip-sec-titles">
                  <h2 className="cs-ip-sec-title">مدرس و سرپرست کارگاه</h2>
                  <span className="cs-ip-sec-sub">راهبری مستقیم پروژه، حل تمرین و انتقال تجربه</span>
                </div>
              </div>
              <span className="cs-ip-sec-badge">راهبر کارگاه</span>
            </div>

            <div className="cs-ip-sec-body">
              <div className="cs-inperson-teacher-panel">
                <div className="cs-inperson-teacher-card">
                  <div className="teacher-av">{teacher.initial || "آ.ت"}</div>
                  <div className="teacher-info">
                    <h4>{teacher.name}</h4>
                    <span className="teacher-role">{teacher.role}</span>
                    <p className="teacher-bio">{teacher.bio}</p>
                  </div>
                </div>
              </div>
            </div>
          </section>
        </div>
      </div>

      {/* مودال تسویه و پرداخت */}
      <CheckoutModal
        isOpen={checkoutOpen}
        onClose={() => setCheckoutOpen(false)}
        course={course}
      />
    </main>
  );
}
