/* ============================================================
   ورود / ثبت‌نام / فراموشی رمز: Auth
   دیزاین سیستم کالج رکاد: کارت آفست، فیلدهای با بوردر ضخیم،
   کلید کهربایی، نمایش/مخفی‌سازی پسورد، بازیابی رمز عبور
   باز شدن: هش #auth
   ============================================================ */
import { useState, useRef, useEffect } from "react";
import { Lock, Check, Bookmark } from "lucide-react";
import "./auth.css";
import { loginUser } from "@/data/panelStore.js";

const FA = "۰۱۲۳۴۵۶۷۸۹";
const toFa = (n) => String(n).replace(/\d/g, (d) => FA[d]);

const PhoneIcon = () => (
  <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.2" strokeLinecap="round" strokeLinejoin="round">
    <rect x="5" y="2" width="14" height="20" rx="3" />
    <line x1="10" y1="19" x2="14" y2="19" />
  </svg>
);

const LockIcon = () => (
  <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.2" strokeLinecap="round" strokeLinejoin="round">
    <rect x="4" y="11" width="16" height="10" rx="2" />
    <path d="M8 11V7a4 4 0 0 1 8 0v4" />
  </svg>
);

const EyeIcon = ({ open }) =>
  open ? (
    <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.2" strokeLinecap="round" strokeLinejoin="round">
      <path d="M1 12s4-8 11-8 11 8 11 8-4 8-11 8-11-8-11-8z" />
      <circle cx="12" cy="12" r="3" />
    </svg>
  ) : (
    <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.2" strokeLinecap="round" strokeLinejoin="round">
      <path d="M17.94 17.94A10.07 10.07 0 0 1 12 20c-7 0-11-8-11-8a18.45 18.45 0 0 1 5.06-5.94M9.9 4.24A9.12 9.12 0 0 1 12 4c7 0 11 8 11 8a18.5 18.5 0 0 1-2.16 3.19m-6.72-1.07a3 3 0 1 1-4.24-4.24" />
      <line x1="1" y1="1" x2="23" y2="23" />
    </svg>
  );

export default function Auth() {
  const [mode, setMode] = useState(() => {
    if (typeof window !== "undefined" && window.location.hash.includes("register")) {
      return "register";
    }
    return "login";
  }); // login | register | forgot
  const [sent, setSent] = useState(false);
  const [forgotStep, setForgotStep] = useState(1); // 1: phone, 2: otp + new pass + confirm, 3: success
  const [showPass, setShowPass] = useState(false);
  const [showNewPass, setShowNewPass] = useState(false);
  const [showConfirmPass, setShowConfirmPass] = useState(false);

  // فرم فراموشی رمز
  const [newPass, setNewPass] = useState("");
  const [confirmPass, setConfirmPass] = useState("");
  const [passError, setPassError] = useState("");
  const [showConfirmModal, setShowConfirmModal] = useState(false);

  // مدیریت OTP تعاملی برای ورود و فراموشی
  const [loginOtp, setLoginOtp] = useState(["", "", "", "", ""]);
  const [forgotOtp, setForgotOtp] = useState(["", "", "", "", ""]);

  const loginOtpRefs = useRef([]);
  const forgotOtpRefs = useRef([]);

  const handleOtpChange = (index, value, isForgotOtp = false) => {
    // تبدیل اعداد فارسی به انگلیسی
    const cleanVal = value.replace(/[۰-۹]/g, (d) => "۰۱۲۳۴۵۶۷۸۹".indexOf(d)).slice(-1);
    const otpArray = isForgotOtp ? [...forgotOtp] : [...loginOtp];
    const setOtpFn = isForgotOtp ? setForgotOtp : setLoginOtp;
    const refs = isForgotOtp ? forgotOtpRefs : loginOtpRefs;

    otpArray[index] = cleanVal;
    setOtpFn(otpArray);

    if (cleanVal && index < 4) {
      refs.current[index + 1]?.focus();
    }
  };

  const handleOtpKeyDown = (index, e, isForgotOtp = false) => {
    const otpArray = isForgotOtp ? forgotOtp : loginOtp;
    const refs = isForgotOtp ? forgotOtpRefs : loginOtpRefs;

    if (e.key === "Backspace" && !otpArray[index] && index > 0) {
      refs.current[index - 1]?.focus();
    }
  };

  const handleOtpPaste = (e, isForgotOtp = false) => {
    e.preventDefault();
    const pasteData = e.clipboardData
      .getData("text")
      .replace(/[۰-۹]/g, (d) => "۰۱۲۳۴۵۶۷۸۹".indexOf(d))
      .replace(/\D/g, "")
      .slice(0, 5);

    if (!pasteData) return;
    const newArr = ["", "", "", "", ""];
    for (let i = 0; i < pasteData.length; i++) {
      newArr[i] = pasteData[i];
    }
    if (isForgotOtp) {
      setForgotOtp(newArr);
      forgotOtpRefs.current[Math.min(pasteData.length, 4)]?.focus();
    } else {
      setLoginOtp(newArr);
      loginOtpRefs.current[Math.min(pasteData.length, 4)]?.focus();
    }
  };

  const handleForgotSubmit = (e) => {
    e.preventDefault();
    setPassError("");

    const otpVal = forgotOtp.join("");
    if (otpVal.length < 5) {
      setPassError("لطفاً کد تأیید ۵ رقمی را کامل وارد کنید.");
      return;
    }

    if (newPass.length < 6) {
      setPassError("رمز عبور باید حداقل ۶ کاراکتر باشد.");
      return;
    }

    if (newPass !== confirmPass) {
      setPassError("تکرار رمز عبور با رمز جدید مطابقت ندارد.");
      return;
    }

    // باز کردن کادر تأیید نهایی
    setShowConfirmModal(true);
  };

  const confirmPasswordReset = () => {
    setShowConfirmModal(false);
    setForgotStep(3);
  };

  const isLogin = mode === "login";
  const isForgot = mode === "forgot";

  const hasRedirectNotice = typeof window !== "undefined" && Boolean(sessionStorage.getItem("rokad_auth_redirect"));
  const sessionNoticeMsg = typeof window !== "undefined" ? sessionStorage.getItem("rokad_auth_msg") : null;

  const handleCompleteAuth = (phoneVal) => {
    loginUser({ phone: phoneVal || "09123456789" });
    const target = (typeof window !== "undefined" && sessionStorage.getItem("rokad_auth_redirect")) || "panel";
    if (typeof window !== "undefined") {
      sessionStorage.removeItem("rokad_auth_redirect");
      sessionStorage.removeItem("rokad_auth_msg");
    }
    window.location.hash = target;
  };

  return (
    <main className="auth-page" id="auth">
      {/* پترن پس‌زمینه */}
      <div className="auth-pattern" aria-hidden="true" />

      <div className="auth-card">
        {sessionNoticeMsg ? (
          <div style={{ background: "#FFF0D4", border: "2px solid var(--ink)", padding: "12px 14px", borderRadius: "10px", fontSize: "13px", fontWeight: 800, color: "#7A3E00", marginBottom: "16px", textAlign: "center", boxShadow: "3px 3px 0 var(--ink)", display: "flex", alignItems: "center", justifyContent: "center", gap: 8 }}>
            <Bookmark size={16} />
            <span>{sessionNoticeMsg}</span>
          </div>
        ) : hasRedirectNotice ? (
          <div style={{ background: "var(--college-light, #fffbeb)", border: "2px solid var(--ink)", padding: "10px 14px", borderRadius: "8px 0 8px 0", fontSize: "13px", fontWeight: 800, color: "var(--navy)", marginBottom: "16px", textAlign: "center", boxShadow: "3px 3px 0 var(--college)", display: "flex", alignItems: "center", justifyContent: "center", gap: 6 }}>
            <Lock size={15} />
            <span>برای دسترسی به پنل کاربری هنرجو، لطفاً ابتدا وارد حساب خود شوید.</span>
          </div>
        ) : null}

        {/* برند */}
        <div className="auth-brand">
          <span className="mark">
            <img src="/assets/Shared/Logos/logo-white-512.png" alt="" aria-hidden="true" />
          </span>
          <span className="txt">
            <b>کالج رکاد</b>
            <small>ROKAD COLLEGE</small>
          </span>
        </div>

        {/* تب‌ها یا هدر بازگشت */}
        {!isForgot ? (
          <div className="auth-tabs" role="tablist">
            <button role="tab" aria-selected={isLogin} className={isLogin ? "on" : ""} onClick={() => { setMode("login"); setSent(false); }}>
              ورود
            </button>
            <button role="tab" aria-selected={!isLogin} className={!isLogin ? "on" : ""} onClick={() => { setMode("register"); setSent(false); }}>
              ثبت‌نام
            </button>
          </div>
        ) : (
          <div className="auth-header-back">
            <button
              type="button"
              className="auth-back-btn"
              onClick={() => {
                setMode("login");
                setForgotStep(1);
                setSent(false);
              }}
            >
              <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round">
                <path d="M9 18l6-6-6-6" />
              </svg>
              <span>بازگشت به ورود</span>
            </button>
            <div className="auth-forgot-headline">
              <h3>بازیابی رمز عبور</h3>
              <p>
                {forgotStep === 1
                  ? "شمارهٔ موبایل خود را وارد کنید تا کد تأیید ارسال شود."
                  : forgotStep === 2
                  ? "کد پیامک‌شده و رمز عبور جدید را وارد کنید."
                  : "رمز عبور با موفقیت تغییر یافت!"}
              </p>
            </div>
          </div>
        )}

        {/* ---------- فرم‌های ورود / ثبت‌نام ---------- */}
        {!isForgot ? (
          !sent ? (
            <form
              className="auth-form"
              onSubmit={(e) => {
                e.preventDefault();
                setSent(true);
              }}
            >
              <label className="auth-field">
                <span className="lbl">
                  <PhoneIcon />
                  شمارهٔ موبایل
                </span>
                <input
                  type="tel"
                  dir="ltr"
                  placeholder="۰۹۱۲۳۴۵۶۷۸۹"
                  required
                  pattern="[0-9۰-۹]{11}"
                  inputMode="numeric"
                />
              </label>

              {!isLogin && (
                <label className="auth-field">
                  <span className="lbl">
                    <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.2" strokeLinecap="round" strokeLinejoin="round">
                      <path d="M20 21v-2a4 4 0 0 0-4-4H8a4 4 0 0 0-4 4v2" />
                      <circle cx="12" cy="7" r="4" />
                    </svg>
                    نام و نام خانوادگی
                  </span>
                  <input type="text" placeholder="مثلاً پارسا محمدی" required />
                </label>
              )}

              <label className="auth-field">
                <span className="lbl">
                  <LockIcon />
                  رمز عبور
                </span>
                <div className="auth-input-wrap">
                  <input
                    type={showPass ? "text" : "password"}
                    placeholder="••••••••"
                    required
                    minLength={6}
                  />
                  <button
                    type="button"
                    className="auth-eye-btn"
                    onClick={() => setShowPass((v) => !v)}
                    aria-label={showPass ? "مخفی‌سازی رمز" : "نمایش رمز"}
                  >
                    <EyeIcon open={showPass} />
                  </button>
                </div>
              </label>

              {isLogin && (
                <button
                  type="button"
                  className="auth-forgot"
                  onClick={() => {
                    setMode("forgot");
                    setForgotStep(1);
                  }}
                >
                  فراموشی رمز عبور؟
                </button>
              )}

              <button type="submit" className="auth-submit">
                {isLogin ? "ورود به حساب" : "ساخت حساب جدید"}
                <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round">
                  <path d="M19 12H5M12 5l-7 7 7 7" />
                </svg>
              </button>
            </form>
          ) : (
            /* ---------- مرحلهٔ OTP ورود / ثبت‌نام ---------- */
            <div className="auth-otp">
              <div className="otp-ic">
                <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.2" strokeLinecap="round" strokeLinejoin="round">
                  <path d="M22 16.92v3a2 2 0 0 1-2.18 2 19.79 19.79 0 0 1-8.63-3.07 19.5 19.5 0 0 1-6-6 19.79 19.79 0 0 1-3.07-8.67A2 2 0 0 1 4.11 2h3a2 2 0 0 1 2 1.72c.12.9.34 1.79.65 2.63a2 2 0 0 1-.45 2.11L8.09 9.91a16 16 0 0 0 6 6l1.45-1.22a2 2 0 0 1 2.11-.45c.84.31 1.73.53 2.63.65A2 2 0 0 1 22 16.92z" />
                </svg>
              </div>
              <b>کد تایید پیامک شد</b>
              <p>
                کد {toFa(5)} رقمی ارسال‌شده به شماره‌ات رو وارد کن
                <small>(کد تستی دلخواه یا {toFa(12345)} را وارد کنید)</small>
              </p>
              <div className="otp-boxes" dir="ltr" onPaste={(e) => handleOtpPaste(e, false)}>
                {[0, 1, 2, 3, 4].map((i) => (
                  <input
                    key={i}
                    ref={(el) => (loginOtpRefs.current[i] = el)}
                    type="text"
                    maxLength={1}
                    inputMode="numeric"
                    value={loginOtp[i]}
                    onChange={(e) => handleOtpChange(i, e.target.value, false)}
                    onKeyDown={(e) => handleOtpKeyDown(i, e, false)}
                    aria-label={`رقم ${toFa(i + 1)}`}
                  />
                ))}
              </div>
              <button
                type="button"
                className="auth-submit"
                onClick={() => handleCompleteAuth()}
              >
                تایید و ورود
              </button>
              <button className="auth-forgot" onClick={() => setSent(false)}>
                تغییر شماره
              </button>
            </div>
          )
        ) : (
          /* ---------- سناریوی فراموشی رمز عبور ---------- */
          <div className="auth-forgot-flow">
            {forgotStep === 1 && (
              <form
                className="auth-form"
                onSubmit={(e) => {
                  e.preventDefault();
                  setForgotStep(2);
                }}
              >
                <label className="auth-field">
                  <span className="lbl">
                    <PhoneIcon />
                    شمارهٔ موبایل حساب کاربری
                  </span>
                  <input
                    type="tel"
                    dir="ltr"
                    placeholder="۰۹۱۲۳۴۵۶۷۸۹"
                    required
                    pattern="[0-9۰-۹]{11}"
                    inputMode="numeric"
                  />
                </label>
                <button type="submit" className="auth-submit">
                  ارسال کد بازیابی
                  <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round">
                    <path d="M19 12H5M12 5l-7 7 7 7" />
                  </svg>
                </button>
              </form>
            )}

            {forgotStep === 2 && (
              <form className="auth-form" onSubmit={handleForgotSubmit}>
                <div className="auth-otp-hint">
                  <span>کد ۵ رقمی پیامک‌شده را وارد کنید:</span>
                  <small>(کد تستی دلخواه یا {toFa(12345)})</small>
                </div>
                <div className="otp-boxes" dir="ltr" onPaste={(e) => handleOtpPaste(e, true)}>
                  {[0, 1, 2, 3, 4].map((i) => (
                    <input
                      key={i}
                      ref={(el) => (forgotOtpRefs.current[i] = el)}
                      type="text"
                      maxLength={1}
                      inputMode="numeric"
                      value={forgotOtp[i]}
                      onChange={(e) => handleOtpChange(i, e.target.value, true)}
                      onKeyDown={(e) => handleOtpKeyDown(i, e, true)}
                      aria-label={`رقم ${toFa(i + 1)}`}
                    />
                  ))}
                </div>

                <label className="auth-field" style={{ marginTop: 6 }}>
                  <span className="lbl">
                    <LockIcon />
                    رمز عبور جدید
                  </span>
                  <div className="auth-input-wrap">
                    <input
                      type={showNewPass ? "text" : "password"}
                      placeholder="رمز جدید (حداقل ۶ کاراکتر)"
                      required
                      minLength={6}
                      value={newPass}
                      onChange={(e) => {
                        setNewPass(e.target.value);
                        if (passError) setPassError("");
                      }}
                    />
                    <button
                      type="button"
                      className="auth-eye-btn"
                      onClick={() => setShowNewPass((v) => !v)}
                      aria-label={showNewPass ? "مخفی‌سازی رمز" : "نمایش رمز"}
                    >
                      <EyeIcon open={showNewPass} />
                    </button>
                  </div>
                </label>

                <label className="auth-field">
                  <span className="lbl">
                    <LockIcon />
                    تکرار رمز عبور جدید
                  </span>
                  <div className="auth-input-wrap">
                    <input
                      type={showConfirmPass ? "text" : "password"}
                      placeholder="تکرار مجدد رمز عبور جدید"
                      required
                      minLength={6}
                      value={confirmPass}
                      onChange={(e) => {
                        setConfirmPass(e.target.value);
                        if (passError) setPassError("");
                      }}
                    />
                    <button
                      type="button"
                      className="auth-eye-btn"
                      onClick={() => setShowConfirmPass((v) => !v)}
                      aria-label={showConfirmPass ? "مخفی‌سازی رمز" : "نمایش رمز"}
                    >
                      <EyeIcon open={showConfirmPass} />
                    </button>
                  </div>
                </label>

                {passError && (
                  <div className="auth-error-msg" role="alert">
                    <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round">
                      <circle cx="12" cy="12" r="10" />
                      <line x1="12" y1="8" x2="12" y2="12" />
                      <line x1="12" y1="16" x2="12.01" y2="16" />
                    </svg>
                    <span>{passError}</span>
                  </div>
                )}

                <button type="submit" className="auth-submit">
                  ثبت و تأیید رمز جدید
                  <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round">
                    <path d="M19 12H5M12 5l-7 7 7 7" />
                  </svg>
                </button>
              </form>
            )}

            {forgotStep === 3 && (
              <div className="auth-success-box">
                <div className="auth-success-icon">
                  <Check size={26} strokeWidth={3} />
                </div>
                <b>رمز عبور شما با موفقیت تغییر کرد</b>
                <p>اکنون می‌توانید با رمز عبور جدید خود وارد پنل کاربری شوید.</p>
                <button
                  type="button"
                  className="auth-submit"
                  onClick={() => {
                    window.location.hash = "panel";
                  }}
                >
                  ورود مستقیم به پنل
                </button>
              </div>
            )}
          </div>
        )}

        {/* مودال اطمینان از تغییر رمز عبور */}
        {showConfirmModal && (
          <div className="auth-modal-backdrop" onClick={() => setShowConfirmModal(false)}>
            <div className="auth-modal-card" onClick={(e) => e.stopPropagation()} role="dialog" aria-modal="true">
              <div className="auth-modal-ic">
                <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.3" strokeLinecap="round" strokeLinejoin="round">
                  <path d="M10.29 3.86L1.82 18a2 2 0 0 0 1.71 3h16.94a2 2 0 0 0 1.71-3L13.71 3.86a2 2 0 0 0-3.42 0z" />
                  <line x1="12" y1="9" x2="12" y2="13" />
                  <line x1="12" y1="17" x2="12.01" y2="17" />
                </svg>
              </div>
              <h4 className="auth-modal-title">اطمینان از تغییر رمز عبور</h4>
              <p className="auth-modal-desc">
                آیا مطمئن هستید که می‌خواهید رمز عبور حساب کاربری خود را به رمز جدید تغییر دهید؟
              </p>
              <div className="auth-modal-actions">
                <button
                  type="button"
                  className="auth-modal-btn-confirm"
                  onClick={confirmPasswordReset}
                >
                  بله، رمز تغییر کند
                </button>
                <button
                  type="button"
                  className="auth-modal-btn-cancel"
                  onClick={() => setShowConfirmModal(false)}
                >
                  انصراف و ویرایش
                </button>
              </div>
            </div>
          </div>
        )}

        {/* ---------- ورود مهمان + گوگل ---------- */}
        {!isForgot && (
          <div className="auth-guest-wrap">
            <span className="or">یا</span>
            <button
              type="button"
              className="auth-google"
              onClick={() => {
                window.location.hash = "panel";
              }}
            >
              <svg viewBox="0 0 24 24" aria-hidden="true">
                <path fill="#4285F4" d="M23.49 12.27c0-.79-.07-1.54-.19-2.27H12v4.51h6.47c-.29 1.48-1.14 2.73-2.4 3.58v3h3.86c2.26-2.09 3.56-5.17 3.56-8.82z" />
                <path fill="#34A853" d="M12 24c3.24 0 5.95-1.08 7.93-2.91l-3.86-3c-1.08.72-2.45 1.16-4.07 1.16-3.13 0-5.78-2.11-6.73-4.96H1.29v3.09C3.26 21.3 7.31 24 12 24z" />
                <path fill="#FBBC05" d="M5.27 14.29c-.25-.72-.38-1.49-.38-2.29s.14-1.57.38-2.29V6.62H1.29C.47 8.24 0 10.06 0 12s.47 3.76 1.29 5.38l3.98-3.09z" />
                <path fill="#EA4335" d="M12 4.75c1.77 0 3.35.61 4.6 1.8l3.42-3.42C17.95 1.19 15.24 0 12 0 7.31 0 3.26 2.7 1.29 6.62l3.98 3.09C6.22 6.86 8.87 4.75 12 4.75z" />
              </svg>
              ورود با گوگل
            </button>
            <a href="#panel" className="auth-guest">
              <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.2" strokeLinecap="round" strokeLinejoin="round">
                <path d="M15 3h4a2 2 0 0 1 2 2v14a2 2 0 0 1-2 2h-4" />
                <path d="M10 17l5-5-5-5" />
                <path d="M15 12H3" />
              </svg>
              ورود مهمان (ورود مستقیم به پنل)
            </a>
          </div>
        )}

        <p className="auth-terms">
          با ورود، <a href="#faq">قوانین و شرایط</a> کالج رکاد رو می‌پذیری.
        </p>
      </div>
    </main>
  );
}
