import { useState, useRef, useEffect, useCallback } from "react";
import { X, Play } from "lucide-react";
import "./videoPlayer.css";

const FA = "۰۱۲۳۴۵۶۷۸۹";
const toFa = (n) => String(n).replace(/\d/g, (d) => FA[d]);

function formatTime(seconds) {
  if (isNaN(seconds) || seconds === null) return "۰۰:۰۰";
  const s = Math.floor(seconds % 60);
  const m = Math.floor((seconds / 60) % 60);
  const h = Math.floor(seconds / 3600);

  const pad = (num) => (num < 10 ? "0" + num : String(num));

  if (h > 0) {
    return toFa(`${pad(h)}:${pad(m)}:${pad(s)}`);
  }
  return toFa(`${pad(m)}:${pad(s)}`);
}

export default function VideoPlayerModal({
  isOpen,
  onClose,
  videoUrl,
  title = "ویدیو آموزشی کالج رکاد",
  lessonTitle = "پیش‌نمایش رایگان دوره",
  poster = "/assets/StatCard/blue.png",
  lessons = [],
  currentLesson = null,
  onSelectLesson = null,
}) {
  const videoRef = useRef(null);
  const containerRef = useRef(null);
  const hideControlsTimer = useRef(null);

  const [isPlaying, setIsPlaying] = useState(false);
  const [currentTime, setCurrentTime] = useState(0);
  const [duration, setDuration] = useState(0);
  const [buffered, setBuffered] = useState(0);
  const [volume, setVolume] = useState(1);
  const [isMuted, setIsMuted] = useState(false);
  const [playbackRate, setPlaybackRate] = useState(1);
  const [showSpeedMenu, setShowSpeedMenu] = useState(false);
  const [isFullscreen, setIsFullscreen] = useState(false);
  const [controlsVisible, setControlsVisible] = useState(true);
  const [skipAnim, setSkipAnim] = useState(null); // { dir: 'left'|'right', text: '-10s'|'+10s' }

  // ریست و پخش خودکار هنگام باز شدن مودال
  useEffect(() => {
    if (isOpen) {
      document.body.style.overflow = "hidden";
      const v = videoRef.current;
      if (v) {
        v.currentTime = 0;
        const playPromise = v.play();
        if (playPromise !== undefined) {
          playPromise
            .then(() => setIsPlaying(true))
            .catch(() => setIsPlaying(false));
        }
      }
    } else {
      document.body.style.overflow = "";
      if (videoRef.current) {
        videoRef.current.pause();
        setIsPlaying(false);
      }
    }
    return () => {
      document.body.style.overflow = "";
    };
  }, [isOpen, videoUrl]);

  // مدیریت ناپدید شدن خودکار کنترل‌ها هنگام پخش
  const handleMouseMove = () => {
    setControlsVisible(true);
    if (hideControlsTimer.current) clearTimeout(hideControlsTimer.current);
    if (isPlaying) {
      hideControlsTimer.current = setTimeout(() => {
        setControlsVisible(false);
        setShowSpeedMenu(false);
      }, 2800);
    }
  };

  const togglePlay = useCallback(() => {
    const v = videoRef.current;
    if (!v) return;
    if (v.paused) {
      v.play();
      setIsPlaying(true);
    } else {
      v.pause();
      setIsPlaying(false);
    }
  }, []);

  const skipSeconds = useCallback((sec) => {
    const v = videoRef.current;
    if (!v) return;
    const target = Math.max(0, Math.min(v.duration || 0, v.currentTime + sec));
    v.currentTime = target;
    setCurrentTime(target);

    // انیمیشن بازخورد بصری
    setSkipAnim({
      dir: sec < 0 ? "right" : "left",
      text: sec < 0 ? "۱۰ ثانیه عقب" : "۱۰ ثانیه جلو",
    });
    setTimeout(() => setSkipAnim(null), 650);
  }, []);

  const handleSeek = (e) => {
    const v = videoRef.current;
    if (!v) return;
    const seekTo = (parseFloat(e.target.value) / 100) * (v.duration || 1);
    v.currentTime = seekTo;
    setCurrentTime(seekTo);
  };

  const handleVolumeChange = (e) => {
    const val = parseFloat(e.target.value);
    setVolume(val);
    if (videoRef.current) {
      videoRef.current.volume = val;
      videoRef.current.muted = val === 0;
      setIsMuted(val === 0);
    }
  };

  const toggleMute = () => {
    if (!videoRef.current) return;
    if (isMuted) {
      videoRef.current.muted = false;
      setIsMuted(false);
      if (volume === 0) {
        setVolume(0.5);
        videoRef.current.volume = 0.5;
      }
    } else {
      videoRef.current.muted = true;
      setIsMuted(true);
    }
  };

  const handleSpeedSelect = (rate) => {
    setPlaybackRate(rate);
    if (videoRef.current) {
      videoRef.current.playbackRate = rate;
    }
    setShowSpeedMenu(false);
  };

  const toggleFullscreen = () => {
    const container = containerRef.current;
    if (!container) return;

    if (!document.fullscreenElement) {
      container.requestFullscreen().then(() => setIsFullscreen(true)).catch(() => {});
    } else {
      document.exitFullscreen().then(() => setIsFullscreen(false)).catch(() => {});
    }
  };

  // آپدیت زمان و بافر
  const onTimeUpdate = () => {
    const v = videoRef.current;
    if (!v) return;
    setCurrentTime(v.currentTime);

    if (v.buffered.length > 0) {
      const buffEnd = v.buffered.end(v.buffered.length - 1);
      setBuffered((buffEnd / (v.duration || 1)) * 100);
    }
  };

  const onLoadedMetadata = () => {
    const v = videoRef.current;
    if (!v) return;
    setDuration(v.duration || 0);
  };

  // کلیدهای میانبر کیبورد
  useEffect(() => {
    if (!isOpen) return;
    const handleKeyDown = (e) => {
      // اگر کاربر در حال تایپ نیست
      if (["INPUT", "TEXTAREA"].includes(document.activeElement?.tagName)) return;

      switch (e.key) {
        case " ":
        case "k":
        case "K":
          e.preventDefault();
          togglePlay();
          break;
        case "ArrowLeft":
        case "j":
        case "J":
          e.preventDefault();
          skipSeconds(-10);
          break;
        case "ArrowRight":
        case "l":
        case "L":
          e.preventDefault();
          skipSeconds(10);
          break;
        case "ArrowUp":
          e.preventDefault();
          if (videoRef.current) {
            const nextVol = Math.min(1, volume + 0.1);
            setVolume(nextVol);
            videoRef.current.volume = nextVol;
            videoRef.current.muted = false;
            setIsMuted(false);
          }
          break;
        case "ArrowDown":
          e.preventDefault();
          if (videoRef.current) {
            const nextVol = Math.max(0, volume - 0.1);
            setVolume(nextVol);
            videoRef.current.volume = nextVol;
          }
          break;
        case "m":
        case "M":
          e.preventDefault();
          toggleMute();
          break;
        case "f":
        case "F":
          e.preventDefault();
          toggleFullscreen();
          break;
        case "Escape":
          e.preventDefault();
          if (document.fullscreenElement) {
            document.exitFullscreen();
          } else {
            onClose();
          }
          break;
        default:
          break;
      }
    };

    window.addEventListener("keydown", handleKeyDown);
    return () => window.removeEventListener("keydown", handleKeyDown);
  }, [isOpen, togglePlay, skipSeconds, volume, isMuted, onClose]);

  if (!isOpen) return null;

  const progressPercent = duration > 0 ? (currentTime / duration) * 100 : 0;
  const currentVideoSrc = videoUrl || "https://commondatastorage.googleapis.com/gtv-videos-bucket/sample/BigBuckBunny.mp4";

  return (
    <div
      className={`vpm-backdrop ${isOpen ? "open" : ""}`}
      onClick={(e) => {
        if (e.target === e.currentTarget) onClose();
      }}
    >
      <div className="vpm-modal" ref={containerRef} onMouseMove={handleMouseMove}>
        {/* Header */}
        <div className="vpm-header">
          <div className="vpm-header-info">
            <span className="vpm-badge" style={{ display: "inline-flex", alignItems: "center", gap: 5 }}>
              <Play size={11} fill="currentColor" />
              <span>ویدیو پلیر رکاد</span>
            </span>
            <div className="vpm-titles">
              <h3 className="vpm-title">{title}</h3>
              <p className="vpm-subtitle">{lessonTitle}</p>
            </div>
          </div>
          <div className="vpm-header-actions">
            <button className="vpm-close-btn" onClick={onClose} aria-label="بستن پنجره" style={{ display: "grid", placeItems: "center" }}>
              <X size={18} strokeWidth={2.5} />
            </button>
          </div>
        </div>

        {/* Video Canvas Body */}
        <div className="vpm-body">
          <video
            ref={videoRef}
            className="vpm-video-element"
            src={currentVideoSrc}
            poster={poster}
            playsInline
            onTimeUpdate={onTimeUpdate}
            onLoadedMetadata={onLoadedMetadata}
            onPlay={() => setIsPlaying(true)}
            onPause={() => setIsPlaying(false)}
            onEnded={() => setIsPlaying(false)}
            onClick={togglePlay}
          />

          {/* Center Play Overlay */}
          <div className={`vpm-center-overlay ${isPlaying ? "hidden" : ""}`}>
            <button className="vpm-big-play-btn" onClick={togglePlay} aria-label="پخش ویدیو">
              <svg viewBox="0 0 24 24" fill="currentColor">
                <path d="M8 5v14l11-7z" />
              </svg>
            </button>
          </div>

          {/* Feedback Skip Animation */}
          {skipAnim && (
            <div className={`vpm-skip-anim ${skipAnim.dir}`}>
              <span>{skipAnim.text}</span>
            </div>
          )}

          {/* Controls Bar */}
          <div className={`vpm-controls ${!controlsVisible && isPlaying ? "fade-out" : ""}`}>
            {/* Timeline Scrubber */}
            <div className="vpm-timeline-container">
              <div className="vpm-timeline-track">
                <div className="vpm-timeline-buffer" style={{ width: `${buffered}%` }} />
                <div className="vpm-timeline-progress" style={{ width: `${progressPercent}%` }} />
                <div className="vpm-timeline-thumb" style={{ right: `${progressPercent}%` }} />
              </div>
              <input
                type="range"
                min="0"
                max="100"
                step="0.1"
                value={progressPercent || 0}
                onChange={handleSeek}
                className="vpm-timeline-input"
                aria-label="زمان ویدیو"
              />
            </div>

            {/* Buttons Row */}
            <div className="vpm-buttons-row">
              {/* Right: Play / Skip / Volume / Timer (RTL order) */}
              <div className="vpm-btn-group">
                <button className="vpm-ctrl-btn" onClick={togglePlay} aria-label={isPlaying ? "توقف" : "پخش"}>
                  {isPlaying ? (
                    <svg viewBox="0 0 24 24" fill="currentColor">
                      <rect x="6" y="4" width="4" height="16" rx="1" />
                      <rect x="14" y="4" width="4" height="16" rx="1" />
                    </svg>
                  ) : (
                    <svg viewBox="0 0 24 24" fill="currentColor">
                      <path d="M8 5v14l11-7z" />
                    </svg>
                  )}
                </button>

                {/* Skip -10s */}
                <button className="vpm-skip-btn" onClick={() => skipSeconds(-10)} title="۱۰ ثانیه عقب (کلید چپ)">
                  <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.4" width="16" height="16">
                    <path d="M1 4v6h6" />
                    <path d="M3.51 15a9 9 0 1 0 2.13-9.36L1 10" />
                  </svg>
                  <span>۱۰-</span>
                </button>

                {/* Skip +10s */}
                <button className="vpm-skip-btn" onClick={() => skipSeconds(10)} title="۱۰ ثانیه جلو (کلید راست)">
                  <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.4" width="16" height="16">
                    <path d="M23 4v6h-6" />
                    <path d="M20.49 15a9 9 0 1 1-2.13-9.36L23 10" />
                  </svg>
                  <span>۱۰+</span>
                </button>

                {/* Volume & Mute */}
                <div className="vpm-volume-wrap">
                  <button className="vpm-ctrl-btn" onClick={toggleMute} aria-label={isMuted ? "وصل صدا" : "قطع صدا"}>
                    {isMuted || volume === 0 ? (
                      <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.2">
                        <line x1="1" y1="1" x2="23" y2="23" />
                        <path d="M9 9v3a3 3 0 0 0 5.12 2.12M15 9.34V4a3 3 0 0 0-5.94-.6" />
                        <path d="M17 16.95A7 7 0 0 1 5 12v-2m14 0v2a7 7 0 0 1-.11 1.23" />
                        <line x1="12" y1="19" x2="12" y2="23" />
                        <line x1="8" y1="23" x2="16" y2="23" />
                      </svg>
                    ) : (
                      <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.2">
                        <polygon points="11 5 6 9 2 9 2 15 6 15 11 19 11 5" />
                        <path d="M15.54 8.46a5 5 0 0 1 0 7.07" />
                        <path d="M19.07 4.93a10 10 0 0 1 0 14.14" />
                      </svg>
                    )}
                  </button>
                  <input
                    type="range"
                    min="0"
                    max="1"
                    step="0.05"
                    value={isMuted ? 0 : volume}
                    onChange={handleVolumeChange}
                    className="vpm-volume-slider"
                    aria-label="میزان صدا"
                  />
                </div>

                {/* Time Indicator */}
                <div className="vpm-time-display">
                  <span>{formatTime(currentTime)}</span>
                  <span className="total"> / {formatTime(duration)}</span>
                </div>
              </div>

              {/* Left: Speed / Fullscreen / Shortcuts */}
              <div className="vpm-btn-group">
                {/* Speed selector */}
                <div style={{ position: "relative" }}>
                  <button
                    className="vpm-speed-btn"
                    onClick={() => setShowSpeedMenu(!showSpeedMenu)}
                    title="سرعت پخش"
                  >
                    {playbackRate}x
                  </button>

                  {showSpeedMenu && (
                    <div className="vpm-speed-menu">
                      {[0.5, 0.75, 1, 1.25, 1.5, 2].map((rate) => (
                        <button
                          key={rate}
                          className={`vpm-speed-opt ${playbackRate === rate ? "active" : ""}`}
                          onClick={() => handleSpeedSelect(rate)}
                        >
                          {rate}x {rate === 1 ? "(عادی)" : ""}
                        </button>
                      ))}
                    </div>
                  )}
                </div>

                {/* Fullscreen */}
                <button className="vpm-ctrl-btn" onClick={toggleFullscreen} title="تمام‌صفحه (F)">
                  <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.2">
                    {isFullscreen ? (
                      <>
                        <path d="M8 3v3a2 2 0 0 1-2 2H3m18 0h-3a2 2 0 0 1-2-2V3m0 18v-3a2 2 0 0 1 2-2h3M3 16h3a2 2 0 0 1 2 2v3" />
                      </>
                    ) : (
                      <>
                        <path d="M8 3H5a2 2 0 0 0-2 2v3m18 0V5a2 2 0 0 0-2-2h-3m0 18h3a2 2 0 0 0 2-2v-3M3 16v3a2 2 0 0 0 2 2h3" />
                      </>
                    )}
                  </svg>
                </button>
              </div>
            </div>
          </div>
        </div>

        {/* Footer: Lesson switcher drawer if provided */}
        {lessons && lessons.length > 0 && (
          <div className="vpm-footer-lessons">
            <span style={{ fontSize: "11px", fontWeight: 900, color: "#9ca3af", whiteSpace: "nowrap" }}>
              لیست دروس:
            </span>
            {lessons.map((les, idx) => {
              const isActive = currentLesson ? currentLesson.t === les.t : idx === 0;
              return (
                <button
                  key={les.t || idx}
                  className={`vpm-lesson-pill ${isActive ? "active" : ""} ${les.locked ? "locked" : ""}`}
                  onClick={() => {
                    if (!les.locked && onSelectLesson) onSelectLesson(les);
                  }}
                  disabled={les.locked}
                >
                  <span>{les.free ? "رایگان" : les.time || "درس"}</span>
                  <span>{les.t || les.title}</span>
                </button>
              );
            })}
            <div className="vpm-shortcuts-hint">
              کلیدها: Space (توقف/پخش) | ← → (۱۰ ثانیه پرش) | M (بی‌صدا) | F (تمام‌صفحه)
            </div>
          </div>
        )}
      </div>
    </div>
  );
}
