/* ============================================================
   تک‌صفحهٔ دوره: Course Single
   از آرت‌بورد «Course Landing Pages» (ترکیب طرح ۰۵ داشبورد + ۰۱
   ادیتوریال) بازطراحی‌شده با DS رکاد:
   بوردر 2px ink، شدو آفست سخت 2.75px، رادیوس 12/17/24،
   کات‌کورنر متناوب، کهربایی فقط برای تاکید.
   باز شدن: #course/<slug>

   موبایل (≤720px): پلر + عنوان + توضیح یوتیوبی اول صفحه؛
   با اسکرول، همه‌شون می‌شن نوار افقی مینیِ چسبان زیر هدر
   (ویدیوی کوچک راست + play/pause + عنوان) بدون گرفتن ویوپورت زیاد.
   ============================================================ */
import { useEffect, useRef, useState, useMemo } from "react";
import { Search, ArrowLeft, CheckCircle2, Lock, Star as LucideStar, ChevronDown } from "lucide-react";
import "./course.css";
import PatternLayer from "../../components/PatternLayer";
import { getCourseBySlug } from "./courseData.js";
import { getPanelStore, enrollInCourse, toggleWishlist } from "../../data/panelStore.js";
import { isEnrolledIn, isWishlisted as checkWishlisted } from "../../data/selectors.js";
import CheckoutModal from "../Checkout/CheckoutModal.jsx";
import VideoPlayerModal from "../../components/VideoPlayerModal/index.jsx";
import CourseSingleInPerson from "./CourseSingleInPerson.jsx";

const Chevron = ({ open }) => (
  <svg
    viewBox="0 0 24 24"
    fill="none"
    stroke="currentColor"
    strokeWidth="2.6"
    strokeLinecap="round"
    strokeLinejoin="round"
    style={{ width: 16, height: 16, transform: open ? "rotate(180deg)" : "none", transition: "transform .25s ease" }}
  >
    <polyline points="6 9 12 15 18 9" />
  </svg>
);

const Star = ({ on }) => (
  <svg viewBox="0 0 24 24" fill={on ? "var(--college)" : "none"} stroke={on ? "var(--college)" : "var(--ink-light)"} strokeWidth="1.6" style={{ width: 15, height: 15 }}>
    <path d="M12 2l3.09 6.26L22 9.27l-5 4.87 1.18 6.88L12 17.77l-6.18 3.25L7 14.14 2 9.27l6.91-1.01z" />
  </svg>
);

const PlayGlyph = ({ size = 22 }) => (
  <svg viewBox="0 0 24 24" fill="currentColor" style={{ width: size, height: size }}><path d="M8 5v14l11-7z" /></svg>
);
const PauseGlyph = ({ size = 22 }) => (
  <svg viewBox="0 0 24 24" fill="currentColor" style={{ width: size, height: size }}><rect x="6" y="5" width="4" height="14" rx="1" /><rect x="14" y="5" width="4" height="14" rx="1" /></svg>
);

/* ---------- توضیح تاشو (مثل یوتیوب): دکمه فقط وقتی متن کلمپ شده ---------- */
function DescriptionCollapse({ paragraphs, className = "", clampLines = 2 }) {
  const [more, setMore] = useState(false);
  const [clippable, setClippable] = useState(false);
  const bodyRef = useRef(null);

  useEffect(() => {
    const check = () => {
      const el = bodyRef.current;
      if (!el) return;
      if (more) { setClippable(true); return; }
      /* وقتی کلمپه: اگه ارتفاع واقعی > ارتفاع کلمپ‌شده یعنی متن بریده شده */
      const clamped = el.scrollHeight > el.clientHeight + 2;
      setClippable(clamped);
    };
    check();
    window.addEventListener("resize", check);
    return () => window.removeEventListener("resize", check);
  }, [more, paragraphs]);

  return (
    <div className={className}>
      <div
        ref={bodyRef}
        className="cs-clamp-body"
        style={more ? undefined : { display: "-webkit-box", WebkitBoxOrient: "vertical", WebkitLineClamp: clampLines, overflow: "hidden" }}
      >
        {paragraphs.map((p, i) => (
          <p key={i}>{p}</p>
        ))}
      </div>
      {clippable && (
        <button className="cs-desc-more" onClick={() => setMore((v) => !v)} aria-expanded={more}>
          {more ? "کمتر" : "بیشتر"}
          <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.6" strokeLinecap="round" strokeLinejoin="round" style={{ width: 11, height: 11, transform: more ? "rotate(180deg)" : "none", transition: "transform .25s ease" }}>
            <polyline points="6 9 12 15 18 9" />
          </svg>
        </button>
      )}
    </div>
  );
}

/* ---------- پنل: سرفصل‌ها ---------- */
function CurriculumPanel({ course, openChapter, setOpenChapter, onLessonPlay, isEnrolled }) {
  return (
    <div className="cs-curriculum">
      <div className="cs-progress">
        <b>۱۲ فصل · ۴۸ درس · ۳۲ ساعت</b>
        <div className="bar"><span /></div>
        <b>{course.progressLabel}</b>
      </div>

      <div className="cs-chapters">
        {course.chapters.map((ch, i) => {
          const open = openChapter === i;
          return (
            <div key={ch.n} className={`cs-ch${open ? " open" : ""}`}>
              <button className="cs-ch-head" onClick={() => setOpenChapter(open ? -1 : i)} aria-expanded={open}>
                <span className="num">{ch.n}</span>
                <span className="info">
                  <b>{ch.title}</b>
                  <small>{ch.sub}</small>
                </span>
                <span className="dur">{ch.dur}</span>
                <span className="chev"><Chevron open={open} /></span>
              </button>

              {ch.lessons.length > 0 && (
                <div className={`cs-lessons${open ? " open" : ""}`}>
                  {ch.lessons.map((l) => {
                    const canPlay = l.free || isEnrolled;
                    return (
                      <div
                        key={l.t}
                        className={`cs-lesson${canPlay ? " free" : " locked"}`}
                        onClick={() => onLessonPlay(l)}
                        style={{ cursor: "pointer" }}
                        title={canPlay ? "مشاهده درس در ویدیو پلیر" : "قفل - نیازمند ثبت‌نام در دوره"}
                      >
                        <span className="ic">
                          {canPlay ? (
                            <svg viewBox="0 0 24 24" fill="currentColor" style={{ width: 11, height: 11 }}><path d="M8 5v14l11-7z" /></svg>
                          ) : (
                            <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.4" strokeLinecap="round" style={{ width: 13, height: 13 }}>
                              <rect x="4" y="11" width="16" height="10" rx="2" />
                              <path d="M8 11V7a4 4 0 0 1 8 0v4" />
                            </svg>
                          )}
                        </span>
                        <span className="t">{l.t}</span>
                        <span className="tag">{l.free ? "رایگان (پخش) ▶" : isEnrolled ? "پخش درس ▶" : l.time}</span>
                      </div>
                    );
                  })}
                </div>
              )}
            </div>
          );
        })}
      </div>
    </div>
  );
}



/* ---------- پنل: نظرات ---------- */
function ReviewsPanel({ course }) {
  return (
    <div className="cs-panel-body">
      <div className="cs-reviews">
        {course.reviews.map((r) => (
          <div className="cs-review" key={r.name}>
            <div className="cs-review-head">
              <span className="cs-review-av">{r.avatar}</span>
              <div className="cs-review-who">
                <b>{r.name}</b>
                <small>{r.date}</small>
              </div>
              <span className="cs-review-stars" aria-label={`${r.rating} از ۵`}>
                {[1, 2, 3, 4, 5].map((s) => (
                  <Star key={s} on={s <= r.rating} />
                ))}
              </span>
            </div>
            <p>{r.text}</p>
          </div>
        ))}
      </div>
    </div>
  );
}

/* ---------- پنل: پرسش و پاسخ ---------- */
function QaPanel({ course }) {
  return (
    <div className="cs-panel-body">
      <div className="cs-qa">
        {course.qa.map((item) => (
          <div className="cs-qa-item" key={item.q}>
            <b>{item.q}</b>
            <p>{item.a}</p>
          </div>
        ))}
      </div>
    </div>
  );
}

/* ---------- پنل: توضیحات دوره ---------- */
function DescriptionPanel({ course }) {
  const paragraphs = Array.isArray(course.description) && course.description.length > 0
    ? course.description
    : (course.lede ? [course.lede] : []);

  return (
    <div className="cs-panel-body cs-desc-panel">
      {course.lede && (
        <div className="cs-desc-highlight-box">
          <p className="cs-desc-lead">{course.lede}</p>
        </div>
      )}

      {paragraphs.length > 0 && (
        <div className="cs-desc-content">
          {paragraphs.map((p, i) => (
            <p key={i}>{p}</p>
          ))}
        </div>
      )}
    </div>
  );
}

/* ---------- پنل: منابع ---------- */
function ResourcesPanel({ course, isEnrolled, onEnrollClick }) {
  const [downloadMsg, setDownloadMsg] = useState(false);

  const handleDownloadClick = (res) => {
    if (!isEnrolled) {
      onEnrollClick();
      return;
    }
    setDownloadMsg(res.title);
    setTimeout(() => setDownloadMsg(false), 3500);

    // ساخت و شروع دانلود فایل واقعی برای هنرجو
    const content = `کالج رکاد - مرجع مهارت‌آموزی و ورود به بازار کار
نام دوره: ${course.title}
عنوان منبع دانلودی: ${res.title}
نوع فایل: ${res.type || "ZIP/PDF"}
حجم: ${res.size || "۱۰ مگابایت"}
تاریخ دریافت: ${new Date().toLocaleDateString("fa-IR")}

توضیحات: این بسته شامل جزوات دوره، قطعه‌کدهای نمونه و فایل‌های تمرینی است.`;

    const blob = new Blob([content], { type: "text/plain;charset=utf-8" });
    const url = URL.createObjectURL(blob);
    const a = document.createElement("a");
    a.href = url;
    a.download = `${course.slug || "rokad"}_${res.title.replace(/\s+/g, "_")}.txt`;
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    URL.revokeObjectURL(url);
  };

  const Icon = ({ type }) => {
    if (type === "ZIP")
      return (
        <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" style={{ width: 18, height: 18 }}>
          <path d="M21 16V8a2 2 0 0 0-1-1.73l-7-4a2 2 0 0 0-2 0l-7 4A2 2 0 0 0 3 8v8a2 2 0 0 0 1 1.73l7 4a2 2 0 0 0 2 0l7-4A2 2 0 0 0 21 16z" />
          <polyline points="3.27 6.96 12 12.01 20.73 6.96" />
          <line x1="12" y1="22.08" x2="12" y2="12" />
        </svg>
      );
    if (type === "لینک")
      return (
        <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" style={{ width: 18, height: 18 }}>
          <path d="M10 13a5 5 0 0 0 7.54.54l3-3a5 5 0 0 0-7.07-7.07l-1.72 1.71" />
          <path d="M14 11a5 5 0 0 0-7.54-.54l-3 3a5 5 0 0 0 7.07 7.07l1.71-1.71" />
        </svg>
      );
    return (
      <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" style={{ width: 18, height: 18 }}>
        <path d="M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z" />
        <polyline points="14 2 14 8 20 8" />
      </svg>
    );
  };

  return (
    <div className="cs-panel-body">
      {downloadMsg && (
        <div style={{ background: "var(--teal-light)", border: "1.5px solid var(--ink)", padding: "8px 12px", borderRadius: "6px 0 6px 0", fontSize: "12.5px", fontWeight: 800, color: "var(--teal-dark)", marginBottom: 12, display: "flex", alignItems: "center", gap: 6 }}>
          <CheckCircle2 size={16} />
          <span>دانلود فایل «{downloadMsg}» آغاز شد</span>
        </div>
      )}
      {!isEnrolled && (
        <div style={{ background: "#fff8e6", border: "1.5px solid var(--ink)", padding: "10px 14px", borderRadius: "8px 0 8px 0", fontSize: "13px", fontWeight: 700, color: "#8a5b00", marginBottom: 14, display: "flex", alignItems: "center", gap: 6 }}>
          <Lock size={15} style={{ flexShrink: 0 }} />
          <span>فایل‌های دانلودی و سورس پروژه مخصوص دانشجویان دوره است. برای دسترسی به فایل‌ها در دوره ثبت‌نام کنید.</span>
        </div>
      )}
      <div className="cs-resources">
        {course.resources.map((res) => (
          <div
            className={`cs-resource${!isEnrolled ? " locked-res" : ""}`}
            key={res.title}
            onClick={() => handleDownloadClick(res)}
            style={{ cursor: "pointer" }}
          >
            <span className="cs-resource-ic"><Icon type={res.type} /></span>
            <span className="cs-resource-info">
              <b>{res.title}</b>
              <small>{res.type === "لینک" ? "مجموعه لینک آنلاین" : `${res.type} · ${res.size}`}</small>
            </span>
            <span className="cs-resource-dl">
              {isEnrolled ? (
                res.type === "لینک" ? "مشاهده" : "دانلود"
              ) : (
                <span style={{ display: "inline-flex", alignItems: "center", gap: 4 }}>
                  <span>قفل</span>
                  <Lock size={12} />
                </span>
              )}
              {isEnrolled && (
                <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.4" strokeLinecap="round" strokeLinejoin="round" style={{ width: 13, height: 13 }}>
                  {res.type === "لینک" ? <path d="M7 17L17 7M17 7H9M17 7v8" /> : <path d="M12 5v14M5 12l7 7 7-7" />}
                </svg>
              )}
            </span>
          </div>
        ))}
      </div>
    </div>
  );
}

export default function CourseSingle({ slug }) {
  const [tab, setTab] = useState(0);
  const [openChapter, setOpenChapter] = useState(0);
  const [headGone, setHeadGone] = useState(false); /* بلاک بالا از دید خارج شد؟ */
  const headRef = useRef(null);

  const [videoModalOpen, setVideoModalOpen] = useState(false);
  const [activeLesson, setActiveLesson] = useState(null);

  const course = useMemo(() => getCourseBySlug(slug), [slug]);
  const [store, setStore] = useState(getPanelStore);
  const [enrollToast, setEnrollToast] = useState(false);
  const [checkoutOpen, setCheckoutOpen] = useState(false);

  const allLessons = useMemo(() => {
    return (course?.chapters || []).flatMap((ch) => ch.lessons || []);
  }, [course]);

  useEffect(() => {
    const handleStoreChange = (e) => {
      setStore(e.detail || getPanelStore());
    };
    window.addEventListener("rokad_panel_store_changed", handleStoreChange);
    return () => window.removeEventListener("rokad_panel_store_changed", handleStoreChange);
  }, []);

  if (!course) {
    return (
      <main className="cs-page" id="course" style={{ padding: "80px 20px", textAlign: "center", minHeight: "60vh" }}>
        <div style={{ maxWidth: 480, margin: "0 auto", background: "#fff", border: "3px solid var(--ink)", borderRadius: "16px 0 16px 0", padding: "40px 24px", boxShadow: "6px 6px 0 var(--college)" }}>
          <div style={{ display: "flex", justifyContent: "center", marginBottom: "14px" }}>
            <Search size={44} style={{ color: "var(--navy)" }} />
          </div>
          <h2 style={{ fontSize: "22px", fontWeight: 950, color: "var(--navy)", margin: "0 0 12px" }}>دوره مورد نظر یافت نشد</h2>
          <p style={{ fontSize: "14px", color: "var(--ink-subtle)", lineHeight: 1.8, margin: "0 0 24px" }}>
            متأسفانه دوره‌ای با این آدرس وجود ندارد یا ممکن است حذف شده باشد.
          </p>
          <a
            href="#courses-index"
            style={{
              display: "inline-flex",
              alignItems: "center",
              gap: 6,
              background: "var(--college)",
              color: "var(--ink)",
              border: "2px solid var(--ink)",
              borderRadius: "8px 0 8px 0",
              padding: "10px 24px",
              fontWeight: 900,
              textDecoration: "none",
              boxShadow: "3px 3px 0 var(--ink)",
            }}
          >
            <span>مشاهده لیست دوره‌ها</span>
            <ArrowLeft size={16} />
          </a>
        </div>
      </main>
    );
  }

  if (
    course.mode === "in-person" ||
    course.isInPerson ||
    (slug && (slug.includes("bootcamp") || slug.includes("حضوری") || slug.includes("in-person")))
  ) {
    return <CourseSingleInPerson course={course} slug={slug} />;
  }

  const courseSlug = course.slug || slug;
  const isEnrolled = isEnrolledIn(courseSlug, store);
  const isWishlisted = Boolean(store?.auth?.isLoggedIn) && checkWishlisted(courseSlug, store);

  const courseTabs = useMemo(() => {
    const rawTabs = course.tabs || ["سرفصل‌ها", "نظرات", "پرسش و پاسخ", "منابع"];
    const filtered = rawTabs.filter((t) => t !== "توضیحات");
    return ["توضیحات", ...filtered];
  }, [course.tabs]);

  const handleStartPurchase = () => {
    // اگر دوره رایگان است مستقیماً فعال کن
    const isFree = course.price === "رایگان" || course.free === true || course.price === "۰";
    if (isFree) {
      enrollInCourse({
        slug: courseSlug,
        title: course.title,
        teacher: course.teacher?.name || "اساتید کالج رکاد",
        sessions: course.facts?.find((f) => f.k === "مدت زمان")?.v ? `۱۲ فصل · ${course.facts.find((f) => f.k === "مدت زمان").v}` : "۱۲ فصل · ۳۲ ساعت",
      });
      setEnrollToast(true);
      setTimeout(() => { window.location.hash = "panel/courses"; }, 1200);
      return;
    }

    // دوره پولی -> باز کردن مودال تسویه و پرداخت
    setCheckoutOpen(true);
  };

  const handleWishlistToggle = () => {
    toggleWishlist(courseSlug);
  };

  const handleOpenVideo = (lesson = null) => {
    if (lesson && !lesson.free && !isEnrolled) {
      handleStartPurchase();
      return;
    }
    setActiveLesson(lesson || allLessons.find((l) => l.free) || allLessons[0] || null);
    setVideoModalOpen(true);
  };

  return (
    <main className="cs-page" id="course">
      <PatternLayer rotate={0} />

        {/* ---------- Topbar: بردکرامب ---------- */}
        <div className="cs-topbar container">
          <a href="#courses-index" className="cs-back">
            <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.4" strokeLinecap="round" strokeLinejoin="round" style={{ width: 14, height: 14 }}>
              <path d="M19 12H5M12 5l-7 7 7 7" />
            </svg>
            همهٔ دوره‌ها
          </a>
          <nav className="cs-crumbs">
            <a href="#courses-index">دوره‌ها</a>
            <span className="sep">›</span>
            <a href={`#courses-index/${course.department}`}>{course.departmentFa}</a>
            <span className="sep">›</span>
            <b>{course.title}</b>
          </nav>
          <span className="cs-students">
            {course.students} دانشجو
            <span className="avs" aria-hidden="true">
              <span className="av" />
              <span className="av" />
              <span className="av" />
            </span>
          </span>
        </div>

        <div className="cs-grid container">
          {/* ============ ستون پلر: موبایل = اول صفحه / دسکتاپ = مخفی ============ */}
          <div className="cs-player-col" ref={headRef}>
            <div
              className="cs-thumb cs-video"
              style={{ position: "relative", overflow: "hidden", background: "#000", cursor: "pointer" }}
              onClick={() => handleOpenVideo()}
            >
              <img
                src={course.pattern || "/assets/StatCard/blue.png"}
                alt={course.title}
                style={{ width: "100%", height: "100%", objectFit: "cover", display: "block" }}
              />
              <button
                type="button"
                className="play"
                onClick={(e) => {
                  e.stopPropagation();
                  handleOpenVideo();
                }}
                aria-label="پخش ویدیو با پلیر پیشرفته"
              >
                <span><PlayGlyph /></span>
              </button>
            </div>

            {/* عنوان + مدرس (فقط موبایل) */}
            <div className="cs-title-row">
              <h1>{course.title}</h1>
              <small className="cs-title-sub" style={{ display: "flex", alignItems: "center", gap: 6 }}>
                <span>{course.teacher.name}</span>
                <span>·</span>
                <LucideStar size={13} fill="#F8A41D" stroke="#F8A41D" />
                <span>۴.۹</span>
                <span>·</span>
                <span>{course.students} دانشجو</span>
              </small>
            </div>
          </div>

          {/* ================= ستون اصلی ================= */}
          <div className="cs-main">
            {/* Hero */}
            <div className="cs-hero">
              <h1>
                <span style={{ display: "inline-block", transform: "rotate(-0.5deg)" }}>{course.title}</span>
              </h1>
              <div className="cs-meta">
                {course.meta.map((m) => (
                  <span className="m" key={m}>{m}</span>
                ))}
              </div>
            </div>

            {/* Tabs */}
            <div className="cs-tabs" role="tablist">
              {courseTabs.map((t, i) => (
                <button
                  key={t}
                  role="tab"
                  aria-selected={tab === i}
                  className={tab === i ? "on" : ""}
                  onClick={() => setTab(i)}
                >
                  {t}
                </button>
              ))}
            </div>

            {/* Panels */}
            {tab === 0 && <DescriptionPanel course={course} />}
            {tab === 1 && (
              <CurriculumPanel
                course={course}
                openChapter={openChapter}
                setOpenChapter={setOpenChapter}
                onLessonPlay={handleOpenVideo}
                isEnrolled={isEnrolled}
              />
            )}
            {tab === 2 && <ReviewsPanel course={course} />}
            {tab === 3 && <QaPanel course={course} />}
            {tab === 4 && <ResourcesPanel course={course} isEnrolled={isEnrolled} onEnrollClick={handleStartPurchase} />}
          </div>

          {/* ================= سایدبار ================= */}
          <aside className="cs-side">
            <div className="cs-card">
              <div
                className="cs-thumb cs-thumb-side"
                onClick={() => handleOpenVideo()}
                style={{ cursor: "pointer" }}
                title="کلیک برای پخش ویدیو با پلیر پیشرفته"
              >
                <span className="play">
                  <span>
                    <svg viewBox="0 0 24 24" fill="currentColor"><path d="M8 5v14l11-7z" /></svg>
                  </span>
                </span>
              </div>

              <div className="cs-price">
                <span className="old">{course.oldPrice}</span>
                <b>{course.price}</b>
                <span className="cur">تومان</span>
              </div>
              <span className="cs-discount">{course.discount}</span>

              {enrollToast && (
                <div style={{ background: "var(--teal-light)", border: "1.5px solid var(--ink)", padding: "8px 10px", borderRadius: "6px 0 6px 0", fontSize: "12.5px", fontWeight: 800, color: "var(--teal-dark)", margin: "8px 0" }}>
                  ثبت‌نام انجام شد! در حال انتقال به پنل…
                </div>
              )}

              {isEnrolled ? (
                <button
                  type="button"
                  className="cs-btn"
                  style={{ background: "var(--teal-dark)", color: "#fff", display: "flex", alignItems: "center", justifyContent: "center", gap: 6 }}
                  onClick={() => { window.location.hash = "panel/courses"; }}
                >
                  <CheckCircle2 size={16} />
                  <span>ثبت‌نام شده (ورود به کلاس)</span>
                </button>
              ) : (
                <button type="button" className="cs-btn" onClick={handleStartPurchase}>
                  {course.price === "رایگان" || course.free ? "ثبت‌نام رایگان (شروع دوره)" : "خرید و ثبت‌نام در دوره"}
                </button>
              )}

              <button
                type="button"
                className="cs-sub-btn"
                onClick={handleWishlistToggle}
                style={{ color: isWishlisted ? "var(--accent)" : "inherit", display: "inline-flex", alignItems: "center", justifyContent: "center", gap: 6 }}
              >
                <LucideStar size={15} fill={isWishlisted ? "currentColor" : "none"} />
                <span>{isWishlisted ? "در لیست علاقه‌مندی‌ها" : "افزودن به علاقه‌مندی‌ها"}</span>
              </button>

              <div className="cs-divider" />

              <div className="cs-facts">
                {course.facts.map((f) => (
                  <div className="f" key={f.k}>
                    <div className="k">{f.k}</div>
                    <div className="v">{f.v}</div>
                  </div>
                ))}
              </div>
            </div>

            <div className="cs-instr">
              <span className="av">{course.teacher.initial}</span>
              <span className="who">
                <b>{course.teacher.name}</b>
                <small>{course.teacher.role}</small>
              </span>
            </div>
          </aside>
        </div>

        {/* مودال پرداخت آنلاین و تسویه حساب */}
        <CheckoutModal
          isOpen={checkoutOpen}
          onClose={() => setCheckoutOpen(false)}
          course={course}
        />

        {/* مودال پخش ویدیو پیشرفته با کنترل‌های کامل */}
        <VideoPlayerModal
          isOpen={videoModalOpen}
          onClose={() => setVideoModalOpen(false)}
          videoUrl={course.videoUrl}
          title={course.title}
          lessonTitle={activeLesson ? activeLesson.t : (course.eyebrow || "پیش‌نمایش ویدیو دوره")}
          poster={course.pattern || "/assets/StatCard/blue.png"}
          lessons={allLessons}
          currentLesson={activeLesson}
          onSelectLesson={(les) => setActiveLesson(les)}
        />
      </main>
  );
}
