/* ============================================================
   گفتگو و رزرو جلسات ۱ به ۱ با منتور: Mentor Hub
   دیزاین سیستم کالج رکاد با چت پایدار و سیستم رزرو جلسات
   ============================================================ */
import { useState, useEffect } from "react";
import { Send, Calendar, CheckCircle2, Check, ArrowLeft } from "lucide-react";
import PanelLayout from "./PanelLayout.jsx";
import { mentorChats } from "./panelData.js";
import { getPanelStore, sendMentorMessage, addMentorBooking } from "../../data/panelStore.js";

const FA = "۰۱۲۳۴۵۶۷۸۹";
const toFa = (n) => String(n).replace(/\d/g, (d) => FA[d]);

const SendIcon = () => <Send size={16} strokeWidth={2.4} />;
const CalendarIcon = () => <Calendar size={16} strokeWidth={2.2} />;

const AVAILABLE_SLOTS = [
  { day: "دوشنبه ۱۸ شهریور", time: "۱۶:۳۰", id: "s1" },
  { day: "چهارشنبه ۲۰ شهریور", time: "۱۱:۰۰", id: "s2" },
  { day: "پنج‌شنبه ۲۱ شهریور", time: "۱۸:۰۰", id: "s3" },
  { day: "شنبه ۲۳ شهریور", time: "۱۴:۰۰", id: "s4" },
];

export default function Mentor({ onNavigate }) {
  const [store, setStore] = useState(getPanelStore);
  const [activeTab, setActiveTab] = useState("chat"); // 'chat' | 'booking'
  const [activeId, setActiveId] = useState(mentorChats[0].id);
  const [inputVal, setInputVal] = useState("");

  // استیت فرم رزرو جلسه
  const [selectedMentorId, setSelectedMentorId] = useState(mentorChats[0].id);
  const [selectedSlot, setSelectedSlot] = useState(AVAILABLE_SLOTS[0]);
  const [bookingTopic, setBookingTopic] = useState("");
  const [bookingSuccessToast, setBookingSuccessToast] = useState(false);

  useEffect(() => {
    const handleStoreChange = (e) => {
      setStore(e.detail || getPanelStore());
    };
    window.addEventListener("rokad_panel_store_changed", handleStoreChange);
    return () => window.removeEventListener("rokad_panel_store_changed", handleStoreChange);
  }, []);

  const active = mentorChats.find((m) => m.id === activeId) || mentorChats[0];
  const allChats = store.mentorChats || {};
  const currentMessages = allChats[activeId] || [
    { from: "them", text: `سلام پارسا جان! من ${active.name} هستم. چطور می‌تونم در این دوره کمکت کنم؟` }
  ];

  const handleSend = (e) => {
    e?.preventDefault();
    if (!inputVal.trim()) return;
    const text = inputVal.trim();
    setInputVal("");

    sendMentorMessage(activeId, { from: "me", text });

    // پاسخ شبیه‌سازی شده منتور با ذخیره در استور
    setTimeout(() => {
      sendMentorMessage(activeId, {
        from: "them",
        text: "پیامت رو بررسی کردم! کدها و نکات لازم رو برات ارسال می‌کنم.",
      });
    }, 1200);
  };

  const handleBookingSubmit = (e) => {
    e.preventDefault();
    const mentorObj = mentorChats.find((m) => m.id === Number(selectedMentorId)) || mentorChats[0];
    addMentorBooking({
      mentorId: mentorObj.id,
      mentorName: mentorObj.name,
      mentorRole: mentorObj.role,
      date: selectedSlot.day,
      time: selectedSlot.time,
      topic: bookingTopic.trim() || "بررسی تمرین‌ها و مسیر پیشرفت شغلی",
    });

    setBookingSuccessToast(true);
    setBookingTopic("");
    setTimeout(() => setBookingSuccessToast(false), 4000);
  };

  const bookings = store.mentorBookings || [];

  return (
    <section id="panel">
      <PanelLayout page="mentor" onNavigate={onNavigate}>
        <div style={{ display: "flex", justifyContent: "space-between", alignItems: "flex-end", flexWrap: "wrap", gap: 16 }}>
          <div>
            <h1 className="pnl-h1">
              <span className="w" style={{ transform: "rotate(-1.5deg)", display: "inline-block" }}>منتورینگ و</span>{" "}
              <span className="w accent" style={{ transform: "rotate(1.5deg)", display: "inline-block" }}>پشتیبانی</span>
            </h1>
            <p className="pnl-sub">پاسخگویی آنلاین متنی و جلسات خصوصی ۱ به ۱ با منتورهای متخصص رکاد.</p>
          </div>

          {/* تب‌های چت و رزرو */}
          <div style={{ display: "flex", gap: 8, marginBottom: 12 }}>
            <button
              type="button"
              className={`pnl-cbtn ${activeTab === "chat" ? "" : "ghost"}`}
              onClick={() => setActiveTab("chat")}
            >
              گفتگوی متنی
            </button>
            <button
              type="button"
              className={`pnl-cbtn ${activeTab === "booking" ? "" : "ghost"}`}
              onClick={() => setActiveTab("booking")}
            >
              <CalendarIcon />
              رزرو جلسه ۱ به ۱
            </button>
          </div>
        </div>

        {activeTab === "chat" ? (
          <div className="pnl-mentor-grid">
            {/* لیست منتورها */}
            <div className="pnl-panel">
              <h4>
                منتورهای من
                <span className="pnl-pill">{mentorChats.length} منتور</span>
              </h4>
              <div className="pnl-mentor-list">
                {mentorChats.map((m) => (
                  <button
                    key={m.id}
                    className={`pnl-mentor${m.id === activeId ? " on" : ""}`}
                    onClick={() => setActiveId(m.id)}
                  >
                    <span className="ava">
                      {m.initial}
                      {m.online && <i className="online" aria-label="آنلاین" />}
                    </span>
                    <span className="info">
                      <b>{m.name}</b>
                      <span className="last">{m.last}</span>
                    </span>
                    <span className="meta">
                      <small>{m.time}</small>
                      {m.unread > 0 && <i className="unread">{m.unread}</i>}
                    </span>
                  </button>
                ))}
              </div>
            </div>

            {/* چت */}
            <div className="pnl-panel pnl-chat-panel">
              <h4>
                {active.name}
                <span className="pnl-pill">{active.role}</span>
              </h4>

              <div className="pnl-chat">
                {currentMessages.map((msg, i) => (
                  <div key={i} className={`pnl-msg ${msg.from}`}>
                    <span className="ava">{msg.from === "me" ? "پ" : active.initial}</span>
                    <span className="bubble">{msg.text}</span>
                  </div>
                ))}
              </div>

              <form className="pnl-chat-input" onSubmit={handleSend}>
                <input
                  type="text"
                  placeholder="پیامت رو بنویس…"
                  dir="rtl"
                  value={inputVal}
                  onChange={(e) => setInputVal(e.target.value)}
                />
                <button type="submit" className="pnl-cbtn send" aria-label="ارسال">
                  <SendIcon />
                  ارسال
                </button>
              </form>
            </div>
          </div>
        ) : (
          /* ---------- بخش رزرو جلسه ۱ به ۱ با منتور ---------- */
          <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fit, minmax(320px, 1fr))", gap: 24, marginTop: 12 }}>
            {/* فرم رزرو جدید */}
            <div className="pnl-panel" style={{ padding: 24 }}>
              <h3 style={{ margin: "0 0 16px", fontSize: "17.5px", fontWeight: 950, color: "var(--navy)" }}>
                رزرو نوبت جلسه ۱ به ۱
              </h3>

              {bookingSuccessToast && (
                <div style={{ background: "var(--teal-light)", border: "1.5px solid var(--ink)", padding: "10px 14px", borderRadius: "8px 0 8px 0", fontSize: "13px", fontWeight: 800, color: "var(--teal-dark)", marginBottom: 16, display: "flex", alignItems: "center", gap: 6 }}>
                  <CheckCircle2 size={16} />
                  <span>نوبت جلسه با موفقیت رزرو شد و به تقویم رویدادهای شما افزوده گردید.</span>
                </div>
              )}

              <form onSubmit={handleBookingSubmit} style={{ display: "flex", flexDirection: "column", gap: 14 }}>
                <div>
                  <label style={{ display: "block", fontSize: "12.5px", fontWeight: 800, color: "var(--navy)", marginBottom: 6 }}>
                    انتخاب منتور:
                  </label>
                  <select
                    value={selectedMentorId}
                    onChange={(e) => setSelectedMentorId(e.target.value)}
                    style={{ width: "100%", padding: "10px 12px", border: "2px solid var(--ink)", borderRadius: "8px 0 8px 0", fontFamily: "inherit", fontSize: "13.5px", background: "#fff" }}
                  >
                    {mentorChats.map((m) => (
                      <option key={m.id} value={m.id}>{m.name} ({m.role})</option>
                    ))}
                  </select>
                </div>

                <div>
                  <label style={{ display: "block", fontSize: "12.5px", fontWeight: 800, color: "var(--navy)", marginBottom: 6 }}>
                    انتخاب زمان آزاد منتور:
                  </label>
                  <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 8 }}>
                    {AVAILABLE_SLOTS.map((s) => (
                      <button
                        type="button"
                        key={s.id}
                        onClick={() => setSelectedSlot(s)}
                        style={{
                          padding: "8px 10px",
                          border: "2px solid var(--ink)",
                          borderRadius: "6px 0 6px 0",
                          background: selectedSlot.id === s.id ? "var(--college)" : "#fff",
                          fontWeight: selectedSlot.id === s.id ? 900 : 700,
                          fontSize: "12.5px",
                          cursor: "pointer",
                          textAlign: "center",
                          boxShadow: selectedSlot.id === s.id ? "2px 2px 0 var(--ink)" : "none",
                        }}
                      >
                        {s.day} · {s.time}
                      </button>
                    ))}
                  </div>
                </div>

                <div>
                  <label style={{ display: "block", fontSize: "12.5px", fontWeight: 800, color: "var(--navy)", marginBottom: 6 }}>
                    موضوع و موارد مورد بحث در جلسه:
                  </label>
                  <textarea
                    rows={3}
                    placeholder="مثلاً: بررسی معماری کدهای پروژه پایانی، رفع اشکال الگوریتم‌ها یا مشاوره برای مصاحبه شغلی…"
                    value={bookingTopic}
                    onChange={(e) => setBookingTopic(e.target.value)}
                    style={{ width: "100%", padding: "10px 12px", border: "2px solid var(--ink)", borderRadius: "8px 0 8px 0", fontFamily: "inherit", fontSize: "13px" }}
                  />
                </div>

                <button type="submit" className="pnl-cbtn" style={{ padding: "11px", marginTop: 6 }}>
                  تأیید و رزرو قطعی جلسه
                </button>
              </form>
            </div>

            {/* لیست جلسات رزرو شده */}
            <div className="pnl-panel" style={{ padding: 24 }}>
              <h3 style={{ margin: "0 0 16px", fontSize: "17.5px", fontWeight: 950, color: "var(--navy)" }}>
                جلسات رزرو شده من
                <span className="pnl-pill">{toFa(bookings.length)} جلسه</span>
              </h3>

              {bookings.length === 0 ? (
                <div style={{ textAlign: "center", padding: "30px 10px", color: "var(--ink-subtle)", fontSize: "13.5px" }}>
                  هنوز جلسه‌ای رزرو نکرده‌اید. از فرم روبه‌رو می‌توانید اولین نوبت خود را تعیین کنید.
                </div>
              ) : (
                <div style={{ display: "flex", flexDirection: "column", gap: 12 }}>
                  {bookings.map((b) => (
                    <div
                      key={b.id}
                      style={{
                        background: "#fff",
                        border: "2px solid var(--ink)",
                        borderRadius: "10px 0 10px 0",
                        padding: 14,
                        boxShadow: "3px 3px 0 var(--ink-light)",
                      }}
                    >
                      <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 6 }}>
                        <b style={{ fontSize: "14px", color: "var(--navy)" }}>{b.mentorName}</b>
                        <span style={{ background: "var(--teal-light)", color: "var(--teal-dark)", border: "1px solid var(--ink)", borderRadius: "4px 0 4px 0", padding: "2px 8px", fontSize: "11.5px", fontWeight: 800, display: "inline-flex", alignItems: "center", gap: 4 }}>
                          <Check size={12} strokeWidth={3} />
                          <span>تأیید شده</span>
                        </span>
                      </div>
                      <div style={{ fontSize: "12.5px", color: "var(--ink-subtle)", fontWeight: 700, marginBottom: 8, display: "flex", alignItems: "center", gap: 6 }}>
                        <Calendar size={14} />
                        <span>{b.date} · ساعت {b.time}</span>
                      </div>
                      <p style={{ fontSize: "12.5px", color: "var(--ink)", lineHeight: 1.5, margin: "0 0 10px" }}>
                        {b.topic}
                      </p>
                      <a
                        href={b.meetLink}
                        target="_blank"
                        rel="noreferrer"
                        className="pnl-cbtn"
                        style={{ display: "inline-flex", alignItems: "center", gap: 6, padding: "6px 12px", fontSize: "12px", textDecoration: "none" }}
                      >
                        <span>ورود به اتاق جلسه آنلاین</span>
                        <ArrowLeft size={13} />
                      </a>
                    </div>
                  ))}
                </div>
              )}
            </div>
          </div>
        )}
      </PanelLayout>
    </section>
  );
}

