/* ============================================================
   صفحه کاربر (پروفایل هنرجو): Student Profile
   از آرت‌بورد «داشببود + صفحه کاربر» بازطراحی‌شده با DS رکاد.
   متصل به استور با امکان ویرایش اطلاعات و پایش پیشرفت
   ============================================================ */
import { useState, useEffect } from "react";
import { Pencil, CheckCircle2 } from "lucide-react";
import PanelLayout from "./PanelLayout.jsx";
import { getPanelStore, updateProfile } from "../../data/panelStore.js";
import { weeklyActivity, skills, badges } from "./panelData.js";

const CheckGlyph = () => (
  <span className="verified" aria-label="حساب تأییدشده">
    <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="3.5" strokeLinecap="round" strokeLinejoin="round">
      <polyline points="20 6 9 17 4 12" />
    </svg>
  </span>
);

export default function Profile({ onNavigate }) {
  const [store, setStore] = useState(getPanelStore);
  const [editOpen, setEditOpen] = useState(false);
  const [fullName, setFullName] = useState("");
  const [role, setRole] = useState("");
  const [bio, setBio] = useState("");
  const [tagsStr, setTagsStr] = useState("");
  const [saveSuccess, setSaveSuccess] = useState(false);

  useEffect(() => {
    const handleStoreChange = (e) => {
      setStore(e.detail || getPanelStore());
    };
    window.addEventListener("rokad_panel_store_changed", handleStoreChange);
    return () => window.removeEventListener("rokad_panel_store_changed", handleStoreChange);
  }, []);

  const { user } = store;

  const openEditModal = () => {
    setFullName(user.fullName);
    setRole(user.role);
    setBio(user.bio || "");
    setTagsStr(user.tags ? user.tags.join(", ") : "");
    setEditOpen(true);
  };

  const handleSaveProfile = (e) => {
    e.preventDefault();
    const updated = updateProfile({
      fullName: fullName.trim(),
      firstName: fullName.trim().split(" ")[0] || "کاربر",
      initial: fullName.trim()[0] || "پ",
      role: role.trim(),
      bio: bio.trim(),
      tags: tagsStr.split(/[,،]/).map((t) => t.trim()).filter(Boolean),
    });
    setEditOpen(false);
    setSaveSuccess(true);
    setTimeout(() => setSaveSuccess(false), 3000);
  };

  return (
    <section id="panel">
      <PanelLayout page="profile" onNavigate={onNavigate}>
        {/* ---------- Greeting ---------- */}
        <div style={{ display: "flex", justifyContent: "space-between", alignItems: "flex-start", flexWrap: "wrap", gap: 12 }}>
          <div>
            <h1 className="pnl-h1">
              <span className="w" style={{ transform: "rotate(-1.5deg)", display: "inline-block" }}>پروفایل</span>{" "}
              <span className="w accent" style={{ transform: "rotate(1.5deg)", display: "inline-block" }}>من</span>
            </h1>
            <p className="pnl-sub">مسیر یادگیری، مهارت‌ها و دستاوردهایت این‌جا خلاصه شده.</p>
          </div>
          <button
            type="button"
            className="pnl-cbtn"
            style={{ padding: "9px 18px", fontSize: "13px", display: "inline-flex", alignItems: "center", gap: 6 }}
            onClick={openEditModal}
          >
            <Pencil size={15} />
            <span>ویرایش پروفایل</span>
          </button>
        </div>

        {saveSuccess && (
          <div
            style={{
              background: "var(--teal-light)",
              border: "2px solid var(--ink)",
              padding: "10px 16px",
              borderRadius: "8px 0 8px 0",
              fontWeight: 800,
              fontSize: "13px",
              color: "var(--teal-dark)",
              marginBottom: 16,
              boxShadow: "2.5px 2.5px 0 var(--ink)",
              display: "flex",
              alignItems: "center",
              gap: 6,
            }}
          >
            <CheckCircle2 size={16} />
            <span>اطلاعات پروفایل شما با موفقیت ذخیره و به‌روزرسانی شد</span>
          </div>
        )}

        <div className="pnl-prof-wrap">
          {/* ---------- Left: identity + level ---------- */}
          <div>
            <div className="pnl-prof">
              <div className="pnl-cover">
                <img src="/assets/Hero/Hero-Pattern.png" alt="" aria-hidden="true" />
                <span className="glyphs" aria-hidden="true">✦ ◆ ✦</span>
              </div>
              <div className="pnl-avatar-lg">
                {user.initial}
                <CheckGlyph />
              </div>
              <div className="pnl-prof-body">
                <h2>{user.fullName}</h2>
                <div className="role">{user.role}</div>
                {user.bio && (
                  <p style={{ fontSize: "12.5px", color: "var(--ink-subtle)", margin: "8px 0 12px", lineHeight: 1.6 }}>
                    {user.bio}
                  </p>
                )}
                <div className="pnl-tags">
                  {user.tags && user.tags.map((t) => (
                    <span className="pnl-tag" key={t}>{t}</span>
                  ))}
                </div>
                <div className="pnl-prof-stats">
                  {user.stats && user.stats.map((s) => (
                    <div key={s.label}>
                      <b>{s.num}</b>
                      <span>{s.label}</span>
                    </div>
                  ))}
                </div>
              </div>
            </div>

            {/* level card */}
            <div className="pnl-level">
              <div>
                <div className="lbl">سطح فعلی</div>
                <h3>{user.level?.title || "محقق برتر"}</h3>
                <small>{user.level?.pointsToNext || "۵۲۰ امتیاز تا سطح بعد"}</small>
              </div>
              <div className="pnl-lvl-circle">{user.level?.number || 7}</div>
              <div className="pnl-lvl-bar">
                <i style={{ width: `${user.level?.pct || 72}%` }} />
              </div>
            </div>
          </div>

          {/* ---------- Right: activity + skills + badges ---------- */}
          <div className="pnl-right">
            <div className="pnl-panel">
              <h4>
                فعالیت هفتگی
                <span className="pnl-pill">+۱۲٪ نسبت به هفته قبل</span>
              </h4>
              <div className="pnl-chart">
                {weeklyActivity.map((b) => (
                  <div key={b.day} className={`pnl-bar${b.hi ? " hi" : ""}`} style={{ height: `${b.pct}%` }}>
                    {b.hours}س
                    <span>{b.day}</span>
                  </div>
                ))}
              </div>
            </div>

            <div className="pnl-panel">
              <h4>مهارت‌های تخصصی</h4>
              {skills.map((s) => (
                <div className="pnl-skill" key={s.name}>
                  <div className="n">{s.name}</div>
                  <div className="track"><i style={{ width: `${s.pct}%` }} /></div>
                  <div className="pct">{s.pct.toLocaleString("fa-IR")}٪</div>
                </div>
              ))}
            </div>

            <div className="pnl-panel">
              <h4>
                دستاوردها
                <span className="pnl-pill">۵ از ۸</span>
              </h4>
              <div className="pnl-badges">
                {badges.map((b, i) => (
                  <div key={i} className={`pnl-badge ${b.cls}`}>
                    <b>{b.label}</b>
                  </div>
                ))}
              </div>
            </div>
          </div>
        </div>

        {/* ---------- مودال ویرایش پروفایل ---------- */}
        {editOpen && (
          <div className="auth-modal-backdrop" onClick={() => setEditOpen(false)}>
            <div className="auth-modal-card" style={{ maxWidth: 460, textAlign: "right", padding: 22 }} onClick={(e) => e.stopPropagation()}>
              <h3 style={{ margin: "0 0 16px", fontSize: "17.5px", fontWeight: 950, color: "var(--navy)" }}>
                ویرایش مشخصات کاربری
              </h3>

              <form onSubmit={handleSaveProfile} style={{ width: "100%", display: "flex", flexDirection: "column", gap: 12 }}>
                <div>
                  <label style={{ display: "block", fontSize: "12.5px", fontWeight: 800, marginBottom: 4, color: "var(--navy)" }}>
                    نام و نام خانوادگی:
                  </label>
                  <input
                    type="text"
                    required
                    dir="rtl"
                    value={fullName}
                    onChange={(e) => setFullName(e.target.value)}
                    style={{ width: "100%", padding: "9px 12px", border: "2px solid var(--ink)", borderRadius: "8px 0 8px 0", fontFamily: "inherit", fontSize: "13.5px" }}
                  />
                </div>

                <div>
                  <label style={{ display: "block", fontSize: "12.5px", fontWeight: 800, marginBottom: 4, color: "var(--navy)" }}>
                    رشته / عنوان تحصیلی و شغلی:
                  </label>
                  <input
                    type="text"
                    required
                    dir="rtl"
                    value={role}
                    onChange={(e) => setRole(e.target.value)}
                    style={{ width: "100%", padding: "9px 12px", border: "2px solid var(--ink)", borderRadius: "8px 0 8px 0", fontFamily: "inherit", fontSize: "13.5px" }}
                  />
                </div>

                <div>
                  <label style={{ display: "block", fontSize: "12.5px", fontWeight: 800, marginBottom: 4, color: "var(--navy)" }}>
                    درباره من / بیوگرافی:
                  </label>
                  <textarea
                    rows={3}
                    dir="rtl"
                    value={bio}
                    onChange={(e) => setBio(e.target.value)}
                    placeholder="توضیح کوتاه درباره اهداف آموزشی…"
                    style={{ width: "100%", padding: "9px 12px", border: "2px solid var(--ink)", borderRadius: "8px 0 8px 0", fontFamily: "inherit", fontSize: "13px" }}
                  />
                </div>

                <div>
                  <label style={{ display: "block", fontSize: "12.5px", fontWeight: 800, marginBottom: 4, color: "var(--navy)" }}>
                    برچسب‌های علاقه‌مندی و مهارت (با کاما جدا کنید):
                  </label>
                  <input
                    type="text"
                    dir="rtl"
                    value={tagsStr}
                    onChange={(e) => setTagsStr(e.target.value)}
                    placeholder="Python, React, Machine Learning"
                    style={{ width: "100%", padding: "9px 12px", border: "2px solid var(--ink)", borderRadius: "8px 0 8px 0", fontFamily: "inherit", fontSize: "13px" }}
                  />
                </div>

                <div style={{ display: "flex", gap: 10, marginTop: 8 }}>
                  <button type="submit" className="pnl-cbtn" style={{ flex: 1, padding: "10px" }}>
                    ذخیره تغییرات
                  </button>
                  <button
                    type="button"
                    className="pnl-cbtn ghost"
                    style={{ flex: 1, padding: "10px" }}
                    onClick={() => setEditOpen(false)}
                  >
                    انصراف
                  </button>
                </div>
              </form>
            </div>
          </div>
        )}
      </PanelLayout>
    </section>
  );
}
