/* گوش دادن به رویداد storage مرورگر برای همگام‌سازی بین تب‌های مختلف */
if (typeof window !== "undefined") {
  window.addEventListener("storage", (e) => {
    if (e.key === STORAGE_KEY && e.newValue) {
      try {
        const updatedState = JSON.parse(e.newValue);
        window.dispatchEvent(new CustomEvent("rokad_panel_store_changed", { detail: updatedState }));
      } catch (err) {
        console.error("Error syncing across tabs:", err);
      }
    }
  });
}

/* ذخیره و لود از localStorage */
export function getPanelStore() {
  if (typeof window === "undefined") return DEFAULT_STATE;
  try {
    const raw = localStorage.getItem(STORAGE_KEY);
    if (!raw) {
      localStorage.setItem(STORAGE_KEY, JSON.stringify(DEFAULT_STATE));
      return DEFAULT_STATE;
    }
    return JSON.parse(raw);
  } catch (err) {
    console.error("Error reading panelStore:", err);
    return DEFAULT_STATE;
  }
}

export function savePanelStore(state) {
  if (typeof window === "undefined") return;
  try {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(state));
    window.dispatchEvent(new CustomEvent("rokad_panel_store_changed", { detail: state }));
  } catch (err) {
    console.error("Error saving panelStore:", err);
  }
}

