import { useState, useEffect, useRef, useMemo } from "react";
import { HelpCircle, GraduationCap, MessageSquare, Check, Star } from "lucide-react";
import Logo from "../Logo.jsx";
import { getPanelStore } from "../../data/panelStore.js";
import { getUnreadNotificationsCount, getUserProfile, isEnrolledIn, isWishlisted } from "../../data/selectors.js";

// Rotations for menu links (sticker feel)
const ROTS = [-1, 0.5, -0.5, 1, -1, 0.5];

/* ─── Searchable site content with thumbnails ─── */
const searchableData = [
  { section: "دوره‌ها", title: "طراحی سایت با وردپرس", text: "از آشنایی با وردپرس تا طراحی سایت حرفه‌ای", link: "#course/wordpress-pro", slug: "wordpress-pro", tags: "وردپرس wordpress وب طراحی سایت", image: "/assets/StatCard/blue.png" },
  { section: "دوره‌ها", title: "برنامه‌نویسی فرانت‌اند", text: "با HTML، CSS و JavaScript وارد دنیای توسعه وب شو", link: "#course/frontend-react", slug: "frontend-react", tags: "javascript react فرانت‌اند frontend html css", image: "/assets/StatCard/teal.png" },
  { section: "دوره‌ها", title: "سئو و بهینه‌سازی سایت", text: "بهینه‌سازی سایت برای موتورهای جست‌وجو", link: "#course/seo-pro", slug: "seo-pro", tags: "seo سئو بهینه‌سازی google analytics", image: "/assets/StatCard/green.png" },
  { section: "دوره‌ها", title: "فتوشاپ و طراحی گرافیک", text: "اصول طراحی و Photoshop", link: "#course/graphic-photoshop", slug: "graphic-photoshop", tags: "فتوشاپ photoshop گرافیک طراحی illustrator", image: "/assets/StatCard/pink.png" },
  { section: "دوره‌ها", title: "تدوین و موشن گرافیک", text: "Premiere و After Effects", link: "#course/video-motion", slug: "video-motion", tags: "موشن تدوین premiere after effects ویدیو", image: "/assets/StatCard/magenta.png" },
  { section: "دوره‌ها", title: "زبان انگلیسی (IELTS)", text: "از پایه تا آمادگی آیلتس", link: "#course/ielts-mastery", slug: "ielts-mastery", tags: "زبان انگلیسی ielts آیلتس english", image: "/assets/StatCard/yellow.png" },
  { section: "دوره‌ها", title: "MBA و مهارت‌های مدیریتی", text: "مدیریت و کسب‌وکار", link: "#course/mba-business", slug: "mba-business", tags: "mba مدیریت کسب‌وکار بازار کار", image: "/assets/StatCard/orange.png" },
  { section: "دوره‌ها", title: "طراحی رابط کاربری UI/UX", text: "فیگما و پروتوتایپ", link: "#course/ui-ux", slug: "ui-ux", tags: "ui ux فیگما طراحی تجربه", image: "/assets/StatCard/blue.png" },
  { section: "دپارتمان‌ها", title: "دپارتمان فناوری اطلاعات (IT)", text: "مسیرهای تخصصی وب، برنامه‌نویسی و سئو", link: "#dept/it", tags: "دپارتمان it وب برنامه‌نویسی", image: "/assets/StatCard/blue.png" },
  { section: "دپارتمان‌ها", title: "دپارتمان دیزاین و گرافیک", text: "طراحی لوگو، موشن گرافیک و فتوشاپ", link: "#dept/design", tags: "دپارتمان گرافیک دیزاین هنر", image: "/assets/StatCard/pink.png" },
  { section: "دپارتمان‌ها", title: "دپارتمان زبان و MBA", text: "آیلتس، مکالمه و مهارت‌های نوین کسب‌وکار", link: "#dept/business", tags: "دپارتمان زبان انگلیسی mba کسب و کار", image: "/assets/StatCard/yellow.png" },
  { section: "دپارتمان‌ها", title: "دپارتمان زبان‌های خارجی", text: "انگلیسی، فرانسه، آلمانی و مکالمه", link: "#dept/languages", tags: "دپارتمان زبان خارجی مکالمه", image: "/assets/StatCard/green.png" },
  { section: "وبلاگ", title: "از کجا یادگیری یک مهارت را شروع کنیم؟", text: "مسیر یادگیری مهارت تخصصی", link: "#article/از-کجا-یادگیری-یک-مهارت-تخصصی-را-شروع-کنیم؟", tags: "یادگیری مهارت شروع مسیر شغلی", image: "/assets/StatCard/blue.png" },
  { section: "وبلاگ", title: "۴ دپارتمان کالج رکاد", text: "فناوری اطلاعات، گرافیک، زبان یا MBA؟", link: "#article/۴-دپارتمان-کالج-رکاد؛-کدام-مسیر-برای-تو-بهتر-است؟", tags: "دپارتمان مسیر رشته", image: "/assets/StatCard/yellow.png" },
  { section: "وبلاگ", title: "یادگیری پروژه‌محور", text: "پروژه‌های واقعی سرعت یادگیری را بالا می‌برد", link: "#article/چرا-یادگیری-پروژه‌محور-مسیر-را-کوتاه‌تر-می‌کند؟", tags: "پروژه‌محور پروژه تمرین عملی", image: "/assets/StatCard/teal.png" },
  { section: "سوالات", title: "آیا پیش‌نیاز لازم دارم؟", text: "خیر. از سطح مقدماتی شروع می‌شود", link: "#faq", tags: "پیش‌نیاز مبتدی شروع", icon: <HelpCircle size={18} /> },
  { section: "سوالات", title: "مدرک دریافت می‌کنم؟", text: "گواهینامه داخلی با کد QR", link: "#faq", tags: "مدرک گواهینامه certificate", icon: <GraduationCap size={18} /> },
  { section: "سوالات", title: "پشتیبانی آموزشی دارم؟", text: "منتور اختصاصی و پاسخ‌گویی زیر ۲۴ ساعت", link: "#faq", tags: "پشتیبانی منتور استاد", icon: <MessageSquare size={18} /> },
  { section: "نظرات", title: "سارا (وردپرس)", text: "از پایه شروع کردم، الان فریلنسرم", link: "#comments", tags: "تجربه نظر هنرجو وردپرس فریلنسر", image: "/assets/StatCard/pink.png", avatarText: "س" },
  { section: "نظرات", title: "امیر (فرانت‌اند)", text: "بازار کار لازم داشتم، الان در اسنپ", link: "#comments", tags: "تجربه نظر هنرجو فرانت‌اند استخدام", image: "/assets/StatCard/blue.png", avatarText: "ا" },
  { section: "نظرات", title: "نگار (گرافیک)", text: "از صفر تا حرفه‌ای عالی بود", link: "#comments", tags: "تجربه نظر هنرجو گرافیک فریلنسر", image: "/assets/StatCard/magenta.png", avatarText: "ن" },
  { section: "نظرات", title: "مریم (زبان)", text: "آیلسم رو ۶.۵ گرفتم", link: "#comments", tags: "تجربه نظر هنرجو زبان ielts", image: "/assets/StatCard/yellow.png", avatarText: "م" },
];

function matchItem(item, query) {
  const q = query.toLowerCase().trim();
  if (!q) return false;
  const hay = (item.title + " " + item.text + " " + item.tags + " " + item.section).toLowerCase();
  return q.split(/\s+/).every((w) => hay.includes(w));
}
  
const sectionBadge = {
  "دوره‌ها": { bg: "var(--college-light)", fg: "var(--college-darker)" },
  "دپارتمان‌ها": { bg: "var(--bg-college-tint)", fg: "var(--college-darker)" },
  "وبلاگ": { bg: "var(--bg-lavender)", fg: "var(--navy)" },
  "سوالات": { bg: "var(--bg-college-tint)", fg: "var(--college-darker)" },
  "نظرات": { bg: "var(--teal-light)", fg: "var(--teal-dark)" },
};

export default function Header() {
  const [mobileOpen, setMobileOpen] = useState(false);
  const [searchOpen, setSearchOpen] = useState(false);
  const [query, setQuery] = useState("");
  const [debouncedQuery, setDebouncedQuery] = useState("");
  const [active, setActive] = useState(0);
  const [scrolled, setScrolled] = useState(false);
  const [store, setStore] = useState(getPanelStore);
  const searchRef = useRef(null);
  const searchInputRef = useRef(null);

  // دیبانس کردن کوئری جستجو
  useEffect(() => {
    const t = setTimeout(() => setDebouncedQuery(query), 160);
    return () => clearTimeout(t);
  }, [query]);

  // همگام‌سازی با استور مرکزی
  useEffect(() => {
    const onStoreChange = (e) => setStore(e.detail || getPanelStore());
    window.addEventListener("rokad_panel_store_changed", onStoreChange);
    return () => window.removeEventListener("rokad_panel_store_changed", onStoreChange);
  }, []);

  const user = getUserProfile(store);
  const unreadCount = getUnreadNotificationsCount(store);

  /* Scroll spy: حالت چسبیدهٔ هدر + هایلایت لینک نوبار مطابق صفحهٔ فعلی (روت هش)
     0 صفحهٔ اصلی | 1 دوره‌ها | 2 مجله | 3 پنل */
  useEffect(() => {
    const apply = () => {
      setScrolled(window.scrollY > 80);
      const h = window.location.hash || "";
      setActive(
        h.startsWith("#courses-index") || h.startsWith("#dept/") || h.startsWith("#course/") ? 1
          : h.startsWith("#blog-index") || h.startsWith("#article/") ? 2
          : h.startsWith("#panel") ? 3
          : 0
      );
    };
    window.addEventListener("scroll", apply, { passive: true });
    window.addEventListener("hashchange", apply);
    apply();
    return () => {
      window.removeEventListener("scroll", apply);
      window.removeEventListener("hashchange", apply);
    };
  }, []);

  /* ─── Search logic: filter + group با debounce ─── */
  const results = useMemo(() => {
    if (!debouncedQuery.trim()) return [];
    return searchableData.filter((item) => matchItem(item, debouncedQuery));
  }, [debouncedQuery]);

  const grouped = useMemo(() => {
    const map = {};
    results.forEach((item) => {
      if (!map[item.section]) map[item.section] = [];
      map[item.section].push(item);
    });
    return map;
  }, [results]);

  /* ─── Navigate to a result ─── */
  const handleResultClick = (link) => {
    setSearchOpen(false);
    setQuery("");
    if (link.startsWith("#")) {
      window.location.hash = link.slice(1);
    }
  };

  /* Open search on Cmd/Ctrl + K */
  useEffect(() => {
    const onGlobal = (e) => {
      if ((e.metaKey || e.ctrlKey) && e.key === "k") {
        e.preventDefault();
        setSearchOpen((prev) => !prev);
      }
    };
    document.addEventListener("keydown", onGlobal);
    return () => document.removeEventListener("keydown", onGlobal);
  }, []);

  /* Close search on Escape or click outside */
  useEffect(() => {
    if (!searchOpen) return;
    const onKey = (e) => { if (e.key === "Escape") setSearchOpen(false); };
    const onClick = (e) => {
      if (searchRef.current && !searchRef.current.contains(e.target))
        setSearchOpen(false);
    };
    document.addEventListener("keydown", onKey);
    document.addEventListener("mousedown", onClick);
    document.body.style.overflow = "hidden";
    if (searchInputRef.current) searchInputRef.current.focus();
    return () => {
      document.removeEventListener("keydown", onKey);
      document.removeEventListener("mousedown", onClick);
      document.body.style.overflow = "";
    };
  }, [searchOpen]);

  /* Close mobile menu on Escape and prevent body scroll when open */
  useEffect(() => {
    if (!mobileOpen) return;
    const onKey = (e) => { if (e.key === "Escape") setMobileOpen(false); };
    document.addEventListener("keydown", onKey);
    const prev = document.body.style.overflow;
    document.body.style.overflow = "hidden";
    return () => {
      document.removeEventListener("keydown", onKey);
      document.body.style.overflow = prev;
    };
  }, [mobileOpen]);

  /* لینک‌های نوبار: صفحه‌محور (نه سکشن‌محور) */
  const links = [
    { t: "صفحهٔ اصلی", href: "#top" },
    { t: "دوره‌ها", href: "#courses-index" },
    { t: "مجله", href: "#blog-index" },
    { t: store.auth?.isLoggedIn ? "پنل من" : "ورود هنرجو", href: store.auth?.isLoggedIn ? "#panel" : "#auth" },
  ];

  return (
    <>
      <header
        className={"site-header" + (scrolled ? " scrolled" : "")}
        id="top"
      >
        <div className="v1-header">
          <div className="pill">
            {/* Logo */}
            <Logo />

            {/* Desktop nav: hidden on mobile */}
            <nav className="nav-links">
              {links.map((l, i) => (
                <a
                  key={i}
                  href={l.href}
                  className={"nav-link" + (active === i ? " active" : "")}
                  onClick={() => setActive(i)}
                >
                  {l.t}
                </a>
              ))}
            </nav>

            {/* Actions */}
            <div className="actions">
              <button
                className="ibtn"
                aria-label="جستجو"
                onClick={() => setSearchOpen(true)}
              >
                <svg
                  viewBox="0 0 24 24"
                  fill="none"
                  stroke="currentColor"
                  strokeLinecap="round"
                  strokeLinejoin="round"
                >
                  <circle cx="11" cy="11" r="7" />
                  <path d="M21 21l-4.35-4.35" />
                </svg>
              </button>

              {/* Desktop-only: user profile or login + CTA */}
              {user && store.auth?.isLoggedIn ? (
                <a
                  href="#panel"
                  className="login-pill desktop-only"
                  style={{
                    background: "var(--college-light)",
                    borderColor: "var(--ink)",
                    fontWeight: 900,
                    color: "var(--college-darker)",
                    position: "relative",
                    display: "inline-flex",
                    alignItems: "center",
                    gap: "6px",
                  }}
                  title="ورود به پنل کاربری هنرجو"
                >
                  <span
                    style={{
                      width: "20px",
                      height: "20px",
                      borderRadius: "50%",
                      background: "var(--college)",
                      color: "var(--ink)",
                      display: "grid",
                      placeItems: "center",
                      fontSize: "11px",
                      fontWeight: 900,
                      border: "1px solid var(--ink)",
                    }}
                  >
                    {user.initial || "پ"}
                  </span>
                  <span>{user.firstName || "پنل من"}</span>
                  {unreadCount > 0 && (
                    <span
                      style={{
                        background: "#e02424",
                        color: "#fff",
                        borderRadius: "10px",
                        fontSize: "10px",
                        padding: "1px 5px",
                        fontWeight: 900,
                        lineHeight: 1.1,
                        border: "1px solid var(--ink)",
                      }}
                    >
                      {unreadCount}
                    </span>
                  )}
                </a>
              ) : (
                <a href="#auth" className="login-pill desktop-only">
                  <svg
                    viewBox="0 0 24 24"
                    fill="none"
                    stroke="currentColor"
                    strokeLinecap="round"
                    strokeLinejoin="round"
                  >
                    <path d="M15 3h4a2 2 0 012 2v14a2 2 0 01-2 2h-4" />
                    <path d="M10 17l5-5-5-5" />
                    <path d="M15 12H3" />
                  </svg>
                  ورود / ثبت‌نام
                </a>
              )}
              <a href="#consult" className="cta-pill desktop-only">
                مشاورهٔ رایگان
                <svg
                  viewBox="0 0 24 24"
                  fill="none"
                  stroke="currentColor"
                  strokeLinecap="round"
                  strokeLinejoin="round"
                >
                  <path d="M15 6l-6 6 6 6" />
                </svg>
              </a>

              {/* Mobile hamburger v1 */}
              <button
                className="mobile-menu-btn"
                onClick={() => setMobileOpen(!mobileOpen)}
                aria-label="منو"
                aria-expanded={mobileOpen}
              >
                <span className={`hb1-bars ${mobileOpen ? "hb1-bars--open" : ""}`}>
                  <span></span>
                  <span></span>
                  <span></span>
                </span>
              </button>
            </div>
          </div>
        </div>
      </header>

      {/* Backdrop */}
      <div className={`search-backdrop${searchOpen ? " search-backdrop--open" : ""}`} onClick={() => { setSearchOpen(false); setQuery(""); }} />

      {/* Search panel overlay */}
      <div className={`search-panel${searchOpen ? " search-panel--open" : ""}`} ref={searchRef}>
        <div className="search-panel-inner">
          <div className="search-panel-field">
            <svg
              viewBox="0 0 24 24"
              fill="none"
              stroke="currentColor"
              strokeLinecap="round"
              strokeLinejoin="round"
            >
              <circle cx="11" cy="11" r="7" />
              <path d="M21 21l-4.35-4.35" />
            </svg>
            <input
              ref={searchInputRef}
              type="text"
              placeholder="دوره، مقاله، سوال، نظر... تایپ کنید"
              className="search-panel-input"
              value={query}
              dir="rtl"
              autoFocus
              onChange={(e) => setQuery(e.target.value)}
              onKeyDown={(e) => { if (e.key === "Enter" && results.length > 0) handleResultClick(results[0].link); }}
            />

          </div>
          <button
            className="search-panel-close"
            onClick={() => { setSearchOpen(false); setQuery(""); }}
            aria-label="بستن"
          >
            <svg
              viewBox="0 0 24 24"
              fill="none"
              stroke="currentColor"
              strokeLinecap="round"
              strokeLinejoin="round"
            >
              <line x1="18" y1="6" x2="6" y2="18" />
              <line x1="6" y1="6" x2="18" y2="18" />
            </svg>
          </button>
        </div>

        {/* Results */}
        {query.trim() && (
          <div className="search-panel-results">
            {results.length === 0 && (
              <div className="search-panel-empty">
                <p>چیزی پیدا نشد؛ کلمه دیگری را امتحان کنید</p>
                <div className="search-panel-tags">
                  {["وردپرس", "فرانت‌اند", "سئو", "گرافیک", "زبان"].map((tag) => (
                    <button key={tag} className="search-panel-tag" onClick={() => setQuery(tag)}>{tag}</button>
                  ))}
                </div>
              </div>
            )}
            {Object.keys(grouped).map((section) => {
              const items = grouped[section];
              const sc = sectionBadge[section] || { bg: "var(--bg-neutral)", fg: "var(--ink)" };
              return (
                <div key={section} className="search-group">
                  <div className="search-group-title" style={{ background: sc.bg, color: sc.fg }}>
                    {section}
                    <span className="search-group-cnt">{items.length}</span>
                  </div>
                  {items.map((item) => {
                    const enrolled = item.slug ? isEnrolledIn(item.slug, store) : false;
                    const wished = item.slug ? isWishlisted(item.slug, store) : false;

                    return (
                      <button key={item.title} className="search-hit" onClick={() => handleResultClick(item.link)}>
                        {item.image ? (
                          <div className="search-hit-img-wrap">
                            <img src={item.image} alt={item.title} className="search-hit-thumb" />
                          </div>
                        ) : item.avatarText ? (
                          <div className="search-hit-img-wrap search-hit-avatar">
                            {item.avatarText}
                          </div>
                        ) : item.icon ? (
                          <div className="search-hit-img-wrap search-hit-icon">
                            {item.icon}
                          </div>
                        ) : null}
                        <div className="search-hit-body">
                          <div className="search-hit-title" style={{ display: "flex", alignItems: "center", gap: "6px", flexWrap: "wrap" }}>
                            <span>{item.title}</span>
                            {enrolled && (
                              <span style={{ fontSize: "10px", fontWeight: 800, background: "var(--teal-light)", color: "var(--teal-dark)", border: "1px solid var(--ink)", padding: "1px 5px", borderRadius: "4px", display: "inline-flex", alignItems: "center", gap: 3 }}>
                                <Check size={11} strokeWidth={3} />
                                <span>ثبت‌نام شده</span>
                              </span>
                            )}
                            {wished && (
                              <span style={{ fontSize: "10px", fontWeight: 800, background: "#fff8e6", color: "var(--accent)", border: "1px solid var(--ink)", padding: "1px 5px", borderRadius: "4px", display: "inline-flex", alignItems: "center", gap: 3 }}>
                                <Star size={11} fill="currentColor" />
                                <span>نشان‌شده</span>
                              </span>
                            )}
                          </div>
                          <div className="search-hit-text">{item.text}</div>
                        </div>
                        <svg className="search-hit-arrow" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" width="14" height="14">
                          <path d="M15 6l-6 6 6 6" />
                        </svg>
                      </button>
                    );
                  })}
                </div>
              );
            })}
          </div>
        )}

        {/* Suggestions when empty */}
        {!query.trim() && searchOpen && (
          <div className="search-panel-results">
            <div className="search-panel-empty">
              <p>دوره‌ها، مقالات، سوالات، نظرات...</p>
              <div className="search-panel-tags">
                {["وردپرس", "فرانت‌اند", "سئو", "گرافیک", "زبان", "MBA"].map((tag) => (
                  <button key={tag} className="search-panel-tag" onClick={() => setQuery(tag)}>{tag}</button>
                ))}
              </div>
            </div>
            <div className="search-group">
              <div className="search-group-title" style={{ background: "var(--college-light)", color: "var(--college-darker)" }}>
                پیشنهادهای برتر کالج رکاد
              </div>
              {searchableData.slice(0, 4).map((item) => (
                <button key={item.title} className="search-hit" onClick={() => handleResultClick(item.link)}>
                  {item.image && (
                    <div className="search-hit-img-wrap">
                      <img src={item.image} alt={item.title} className="search-hit-thumb" />
                    </div>
                  )}
                  <div className="search-hit-body">
                    <div className="search-hit-title">{item.title}</div>
                    <div className="search-hit-text">{item.text}</div>
                  </div>
                  <svg className="search-hit-arrow" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" width="14" height="14">
                    <path d="M15 6l-6 6 6 6" />
                  </svg>
                </button>
              ))}
            </div>
          </div>
        )}
      </div>

      {/* Mobile fullscreen amber overlay */}
      <div className={`hb1-panel ${mobileOpen ? "hb1-panel--open" : ""}`}>
        <div className="hb1-panel-head">
          <Logo size={28} />
          <button
            className="hb1-close"
            onClick={() => setMobileOpen(false)}
            aria-label="بستن"
          >
            ×
          </button>
        </div>

        <ul className="hb1-list">
          {links.map((l, i) => (
            <li key={i}>
              <a
                href={l.href}
                onClick={() => {
                  setActive(i);
                  setMobileOpen(false);
                }}
                style={{ transform: `rotate(${ROTS[i]}deg)` }}
              >
                {l.t}
              </a>
              <span className="hb1-chev">‹</span>
            </li>
          ))}
        </ul>

        <div className="hb1-actions" style={{ display: "flex", flexDirection: "column", gap: 10 }}>
          {store.auth?.isLoggedIn ? (
            <a
              href="#panel"
              className="hb1-cta"
              style={{ background: "var(--college-light)", color: "var(--college-darker)", borderColor: "var(--ink)" }}
              onClick={() => setMobileOpen(false)}
            >
              پنل کاربری ({user?.firstName || "هنرجو"})
            </a>
          ) : (
            <a
              href="#auth"
              className="hb1-cta"
              style={{ background: "var(--white)", color: "var(--navy)", borderColor: "var(--navy)" }}
              onClick={() => setMobileOpen(false)}
            >
              ورود / ثبت‌نام
            </a>
          )}
          <a
            href="#consult"
            className="hb1-cta"
            onClick={() => setMobileOpen(false)}
          >
            مشاورهٔ رایگان
          </a>
        </div>
      </div>
    </>
  );
}