/* ============================================================
   تکالیف هنرجو: Assignments page
   از آرت‌بورد داشبورد بازطراحی‌شده با DS رکاد:
   بوردر 2px ink، شدو آفست، چرخش‌های ظریف، توکن‌های کالج.
   متصل به استور و امکان ارسال آنلاین تکالیف
   ============================================================ */
import { useState, useEffect, useRef } from "react";
import { FolderOpen, Award, CheckCircle2 } from "lucide-react";
import PanelLayout from "./PanelLayout.jsx";
import { getPanelStore, submitAssignment } from "../../data/panelStore.js";

const FA = "۰۱۲۳۴۵۶۷۸۹";
const toFa = (n) => String(n).replace(/\d/g, (d) => FA[d]);

/* ---------- Status chip styles ---------- */
const STATUS = {
  open: { label: "باز", cls: "open" },
  late: { label: "در حال گذشتن مهلت", cls: "late" },
  done: { label: "تحویل‌شده", cls: "done" },
  graded: { label: "نمره‌داده‌شده", cls: "graded" },
};

export default function Assignments({ onNavigate }) {
  const [store, setStore] = useState(getPanelStore);
  const [activeModalAssignment, setActiveModalAssignment] = useState(null); // for submission
  const [viewFeedbackAssignment, setViewFeedbackAssignment] = useState(null); // for viewing
  const [submissionText, setSubmissionText] = useState("");
  const [submissionFile, setSubmissionFile] = useState(null);
  const fileInputRef = useRef(null);

  useEffect(() => {
    const handleStoreChange = (e) => {
      setStore(e.detail || getPanelStore());
    };
    window.addEventListener("rokad_panel_store_changed", handleStoreChange);
    return () => window.removeEventListener("rokad_panel_store_changed", handleStoreChange);
  }, []);

  const { assignments } = store;
  const open = assignments.filter((a) => a.status === "open" || a.status === "late");
  const handleFileChange = (e) => {
    const file = e.target.files?.[0];
    if (file) {
      const sizeKb = (file.size / 1024).toFixed(1);
      setSubmissionFile({
        name: file.name,
        size: sizeKb > 1024 ? `${(sizeKb / 1024).toFixed(1)} مگابایت` : `${sizeKb} کیلوبایت`,
      });
    }
  };

  const handleSubmitAssignment = (e) => {
    e.preventDefault();
    if (!activeModalAssignment) return;
    submitAssignment(activeModalAssignment.id, {
      text: submissionText.trim() || "پروژه و کدهای مربوط به این تکلیف با موفقیت ارسال شد.",
      fileName: submissionFile ? submissionFile.name : "solution_project.zip",
    });
    setActiveModalAssignment(null);
    setSubmissionText("");
    setSubmissionFile(null);
  };

  const Row = ({ a }) => {
    const st = STATUS[a.status];
    return (
      <div className={`pnl-asn${a.status === "late" ? " urgent" : ""}`}>
        <div className={`pnl-asn-ic ${st.cls}`}>
          {a.status === "graded" ? (
            <span className="grade">{a.grade}</span>
          ) : (
            <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.4" strokeLinecap="round" strokeLinejoin="round">
              {a.status === "done" ? (
                <polyline points="20 6 9 17 4 12" />
              ) : (
                <>
                  <path d="M12 20h9" />
                  <path d="M16.5 3.5a2.12 2.12 0 0 1 3 3L7 19l-4 1 1-4z" />
                </>
              )}
            </svg>
          )}
        </div>
        <div className="body">
          <b>{a.title}</b>
          <div className="m">
            {a.course} · {a.due} · تمرین {toFa(a.no)}
          </div>
          {a.status === "graded" && (
            <div className="graded-note" style={{ display: "inline-flex", alignItems: "center", gap: 4 }}>
              <CheckCircle2 size={13} style={{ color: "var(--teal-dark)" }} />
              <span>بازخورد منتور ثبت شد (نمره: {a.grade})</span>
            </div>
          )}
          {a.status === "done" && (
            <div className="graded-note" style={{ color: "var(--teal-dark)", display: "inline-flex", alignItems: "center", gap: 4 }}>
              <CheckCircle2 size={13} />
              <span>پاسخ شما با موفقیت ارسال شده است.</span>
            </div>
          )}
        </div>
        <div className="side">
          <span className={`pnl-chip ${st.cls}`}>{st.label}</span>
          {a.status === "open" && (
            <button className="pnl-cbtn" onClick={() => setActiveModalAssignment(a)}>
              شروع و ارسال
            </button>
          )}
          {a.status === "late" && (
            <button className="pnl-cbtn" onClick={() => setActiveModalAssignment(a)}>
              فوری تحویل بده
            </button>
          )}
          {(a.status === "done" || a.status === "graded") && (
            <button className="pnl-cbtn ghost" onClick={() => setViewFeedbackAssignment(a)}>
              مشاهدهٔ جزئیات
            </button>
          )}
        </div>
      </div>
    );
  };

  return (
    <section id="panel">
      <PanelLayout page="assignments" onNavigate={onNavigate}>
        <h1 className="pnl-h1">
          <span className="w" style={{ transform: "rotate(-1.5deg)", display: "inline-block" }}>تکالیف</span>{" "}
          <span className="w accent" style={{ transform: "rotate(1.5deg)", display: "inline-block" }}>من</span>
        </h1>
        <p className="pnl-sub">
          {open.length > 0
            ? `${toFa(open.length)} تکلیف باز داری؛ از مهلت‌دارها شروع کن.`
            : "فعلاً تکلیف بازی نداری؛ همه تکالیف ارسال شده‌اند!"}
        </p>

        {/* ---------- باز ---------- */}
        <div className="pnl-panel">
          <h4>
            باز و در انتظار
            <span className="pnl-pill">{toFa(open.length)} تکلیف</span>
          </h4>
          {open.map((a) => (
            <Row key={a.id} a={a} />
          ))}
          {open.length === 0 && (
            <div style={{ textAlign: "center", padding: "20px", color: "var(--teal-dark)", fontWeight: 800, display: "flex", alignItems: "center", justifyContent: "center", gap: 8 }}>
              <Award size={20} />
              <span>تمامی تکالیف جاری را تحویل داده‌اید. عالی پیش می‌روید!</span>
            </div>
          )}
        </div>

        {/* ---------- تحویل‌شده ---------- */}
        <div className="pnl-panel" style={{ marginTop: 22 }}>
          <h4>
            تحویل‌شده و نمره‌دهی
            <span className="pnl-pill">{toFa(closed.length)} تکلیف</span>
          </h4>
          {closed.map((a) => (
            <Row key={a.id} a={a} />
          ))}
        </div>

        {/* ---------- مودال ارسال تکلیف ---------- */}
        {activeModalAssignment && (
          <div className="auth-modal-backdrop" onClick={() => setActiveModalAssignment(null)}>
            <div className="auth-modal-card" style={{ maxWidth: 480, textAlign: "right" }} onClick={(e) => e.stopPropagation()}>
              <h3 style={{ margin: "0 0 6px", fontSize: "17.5px", fontWeight: 950, color: "var(--navy)" }}>
                ارسال پاسخ: {activeModalAssignment.title}
              </h3>
              <div style={{ fontSize: "12.5px", color: "var(--college-dark)", fontWeight: 800, marginBottom: 12 }}>
                {activeModalAssignment.course} · تمرین شماره {toFa(activeModalAssignment.no)}
              </div>
              <p style={{ fontSize: "13px", color: "var(--ink-subtle)", lineHeight: 1.6, margin: "0 0 16px" }}>
                {activeModalAssignment.description}
              </p>

              <form onSubmit={handleSubmitAssignment} style={{ width: "100%", display: "flex", flexDirection: "column", gap: 12 }}>
                <div>
                  <label style={{ display: "block", fontSize: "12.5px", fontWeight: 800, marginBottom: 6, color: "var(--navy)" }}>
                    توضیحات و یادداشت پاسخ:
                  </label>
                  <textarea
                    rows={4}
                    required
                    dir="rtl"
                    placeholder="توضیحات تکمیلی درباره نحوه پیاده‌سازی یا لینک گیت‌هاب پروژه…"
                    value={submissionText}
                    onChange={(e) => setSubmissionText(e.target.value)}
                    style={{
                      width: "100%",
                      padding: "10px 12px",
                      border: "2px solid var(--ink)",
                      borderRadius: "8px 0 8px 0",
                      fontFamily: "inherit",
                      fontSize: "13.5px",
                    }}
                  />
                </div>

                <div>
                  <label style={{ display: "block", fontSize: "12.5px", fontWeight: 800, marginBottom: 6, color: "var(--navy)" }}>
                    فایل ضمیمه یا سورس کد (ZIP / PDF / IPYNB):
                  </label>
                  <input
                    type="file"
                    ref={fileInputRef}
                    onChange={handleFileChange}
                    style={{ display: "none" }}
                    accept=".zip,.rar,.pdf,.ipynb,.py,.js,.jsx,.ts,.tsx,.png,.jpg"
                  />
                  <div
                    onClick={() => fileInputRef.current?.click()}
                    style={{
                      border: "2px dashed var(--ink)",
                      padding: "16px",
                      borderRadius: "8px 0 8px 0",
                      background: submissionFile ? "var(--teal-light)" : "var(--college-light)",
                      textAlign: "center",
                      fontSize: "13px",
                      fontWeight: 800,
                      color: "var(--navy)",
                      cursor: "pointer",
                      transition: "all 0.2s ease",
                    }}
                  >
                    {submissionFile ? (
                      <div>
                        <div style={{ display: "flex", alignItems: "center", justifyContent: "center", gap: 6 }}>
                          <CheckCircle2 size={16} style={{ color: "var(--teal-dark)" }} />
                          <span>فایل انتخاب شد: <b>{submissionFile.name}</b></span>
                        </div>
                        <small style={{ color: "var(--ink-subtle)", fontWeight: 700 }}>حجم: {submissionFile.size} (کلیک برای تغییر فایل)</small>
                      </div>
                    ) : (
                      <div>
                        <div style={{ display: "flex", alignItems: "center", justifyContent: "center", gap: 6 }}>
                          <FolderOpen size={18} />
                          <span>برای انتخاب یا آپلود فایل پروژه کلیک کنید</span>
                        </div>
                        <small style={{ color: "var(--ink-subtle)", fontWeight: 700 }}>پشتیبانی از فرمت‌های ZIP، PDF، IPYNB و کدهای سورس</small>
                      </div>
                    )}
                  </div>
                </div>

                <div style={{ display: "flex", gap: 10, marginTop: 8 }}>
                  <button type="submit" className="pnl-cbtn" style={{ flex: 1, padding: "10px" }}>
                    ثبت نهایی و تحویل
                  </button>
                  <button
                    type="button"
                    className="pnl-cbtn ghost"
                    style={{ flex: 1, padding: "10px" }}
                    onClick={() => setActiveModalAssignment(null)}
                  >
                    انصراف
                  </button>
                </div>
              </form>
            </div>
          </div>
        )}

        {/* ---------- مودال مشاهده جزئیات و بازخورد منتور ---------- */}
        {viewFeedbackAssignment && (
          <div className="auth-modal-backdrop" onClick={() => setViewFeedbackAssignment(null)}>
            <div className="auth-modal-card" style={{ maxWidth: 460, textAlign: "right" }} onClick={(e) => e.stopPropagation()}>
              <h3 style={{ margin: "0 0 4px", fontSize: "17px", fontWeight: 950, color: "var(--navy)" }}>
                جزئیات تکلیف: {viewFeedbackAssignment.title}
              </h3>
              <div style={{ fontSize: "12.5px", color: "var(--college-dark)", fontWeight: 800, marginBottom: 14 }}>
                {viewFeedbackAssignment.course} · وضعیت: {STATUS[viewFeedbackAssignment.status]?.label}
              </div>

              {viewFeedbackAssignment.grade && (
                <div
                  style={{
                    background: "var(--teal-light)",
                    border: "2px solid var(--ink)",
                    borderRadius: "8px 0 8px 0",
                    padding: "10px 14px",
                    marginBottom: 12,
                    display: "flex",
                    justifyContent: "space-between",
                    alignItems: "center",
                  }}
                >
                  <b style={{ color: "var(--teal-dark)", fontSize: "14px" }}>نمره نهایی منتور:</b>
                  <span style={{ fontSize: "20px", fontWeight: 950, color: "var(--navy)" }}>{viewFeedbackAssignment.grade} از ۲۰</span>
                </div>
              )}

              {viewFeedbackAssignment.feedback && (
                <div style={{ marginBottom: 14 }}>
                  <b style={{ display: "block", fontSize: "13px", color: "var(--navy)", marginBottom: 4 }}>بازخورد و نکات استاد:</b>
                  <p style={{ background: "var(--bg-lavender, #f3f0ff)", padding: "10px 12px", border: "1.5px solid var(--ink)", borderRadius: "6px 0 6px 0", fontSize: "13px", lineHeight: 1.6, margin: 0 }}>
                    {viewFeedbackAssignment.feedback}
                  </p>
                </div>
              )}

              {viewFeedbackAssignment.submission && (
                <div style={{ marginBottom: 14 }}>
                  <b style={{ display: "block", fontSize: "13px", color: "var(--navy)", marginBottom: 4 }}>پاسخ ارسالی شما:</b>
                  <div style={{ background: "#f8f9fa", padding: "10px 12px", border: "1.5px solid var(--ink)", borderRadius: "6px 0 6px 0", fontSize: "12.5px", color: "var(--ink)" }}>
                    <p style={{ margin: "0 0 6px" }}>{viewFeedbackAssignment.submission.text}</p>
                    <small style={{ color: "var(--ink-subtle)" }}>فایل: {viewFeedbackAssignment.submission.fileName} ({viewFeedbackAssignment.submission.date})</small>
                  </div>
                </div>
              )}

              <button
                type="button"
                className="pnl-cbtn wide"
                onClick={() => setViewFeedbackAssignment(null)}
              >
                بستن پنجره
              </button>
            </div>
          </div>
        )}
      </PanelLayout>
    </section>
  );
}
